  <script lang='ts'>
import { notify } from 'src/components/notifications/notify';
  
  
  import { storeToRefs } from 'pinia';
  import dateUtils from 'src/utils/date';
  import { defineComponent, ref } from 'vue';
  import helperUtil from 'src/utils/helperUtil';
  import Loader from 'src/components/Loader.vue';
  import { type dynamicObj, $ } from 'src/pages/assets';
  import helperMixin from 'src/mixins/helperMixin';
  import { documentPOApiService } from 'src/services';
  import poActionsUtil from 'src/utils/poActionsUtil';
  import docTablesUtil from 'src/utils/docTablesUtil';
  import { ApiExceptions } from 'src/exceptions/index';
  import dragDropColumn from 'src/mixins/dragDropColumn';
  import lineItemsBaseMixin from 'src/mixins/lineItemsBaseMixin';
  import { fillToleranceModel } from 'src/utils/poToleranceUtil';
  import resizableGridUtil from 'src/utils/resizableGridUtil';
  import displayFieldLabel from 'src/utils/displayFieldLabel';
  import { removeSpacesAndUnderscore } from 'src/utils/general';
  import { isUserAdmin as checkIsUserAdmin } from 'src/utils/UserDetails';
  import { isUndefinedOrNull } from 'src/utils/general';
  import amountConversionHelper from 'src/utils/amountConversionHelper';
  import { useDocumentStore, usePoMatchStore, useSettingStore, useDocAttributesStore, useMasterDataLookupStore, usePOLineItemsStore } from 'src/store/main';
  import {
    CONSTANTS,
    dateFormates,
    number_column_types,
    includeColumnsForPO,
    AI_table_extraction_setting,
    line_table_columns,
    po_quantities_allowed_decimals,
    PO_LINE_PERMISSION_ALL,
    use_lines_net_amount_permission,
    auto_match_export_permission,
  } from 'src/constants';
  import { useTableHeightResize } from 'src/utils/tableHeightResizeUtil';
  import ColumnFilter from 'src/pages/Dashboard/ColumnFilter.vue';
  import ColumnFilterBadges from 'src/pages/Dashboard/ColumnFilterBadges.vue';
  import QuantityTooltip from 'src/pages/PurchaseOrders/components/QuantityTooltip.vue';
import TolerancePopup from 'src/pages/PurchaseOrders/components/TolerancePopup.vue';
  export default defineComponent({
    el: '#app',
    mixins: [docTablesUtil, helperMixin, helperUtil, amountConversionHelper, poActionsUtil, displayFieldLabel, dateUtils, dragDropColumn, resizableGridUtil, lineItemsBaseMixin],
    props: {
      allowPOTableDrag: {
        type: Boolean,
        default: false
      }
    },
    components: { Loader, ColumnFilter, ColumnFilterBadges, QuantityTooltip, TolerancePopup },
    data() {
      return {
        docId : '',
        is_po_view: false,
        po_dragging: false,
        validation_done: true,
        confirmDialog: ref(false),
        dragging_data: {} as any,
        coveredLineItem: [] as any,
        blockProcessing: ref(false),
        connected_line_item: '',
        misMatchedProperties: '',
        misMatchedList: [] as any,
        percent : CONSTANTS.percent,
        custom_range_for_po_tolerance : CONSTANTS.custom_range_for_po_tolerance,
        number_column_types,
        AI_table_extraction_setting,
        filterValueByField: ref({}) as dynamicObj,
        indexToMove: ref(),
        line_table_columns: line_table_columns,
        tableId: 'line_item_table',
        po_quantities_allowed_decimals,
      };
    },
   
    computed: {
      filteredTableRows() {
        return this.filterByObject(this.tableRows, this.filterValueByField);
      },
      isUserAdmin(): boolean {
        return checkIsUserAdmin();
      },
      canViewAutoMatchAndExport(): boolean {
        return this.isUserAdmin || this.doc_attributes?.[auto_match_export_permission] === PO_LINE_PERMISSION_ALL;
      },
      canViewUseLinesNetAmount(): boolean {
        return this.isUserAdmin || this.doc_attributes?.[use_lines_net_amount_permission] === PO_LINE_PERMISSION_ALL;
      }
    },
    
    mounted: async function() {
      document.addEventListener('init_line_items',this.lineItemDataLoaded);
      document.addEventListener('line_item_table-column-drop', this.savedSortedColumns);
      this.isViewPo();  
      (<any>window).lineItemsPoV3 = this;
      await this.init();
      //document.addEventListener('dragenter',this.dragenter);
      document.addEventListener('dragover',this.dragover);
      // document.addEventListener('drop',this.drop);
      document.addEventListener('keydown',  this.keyDownEvent);
      this.initailizeDragColumnsById(this.tableId);

      await this.$nextTick();
      this.initTableColumnResize(this.tableId);
    },
    unmounted: function() {
      document.removeEventListener('init_line_items',this.lineItemDataLoaded);
      document.removeEventListener('line_item_table-column-drop', this.savedSortedColumns);
     // document.removeEventListener('dragenter',this.dragenter);
      document.removeEventListener('dragover',this.dragover);
      // document.removeEventListener('drop',this.drop);
      document.removeEventListener('keydown',  this.keyDownEvent);
      this.destoryAndRest(this.tableId);
    },
    methods: {
      drop (event: any) {
        event.preventDefault();
        if (!event.target || this.is_view_readonly) {
          return;
        }

        let target = event.target as HTMLElement;

        if (this.allowPOTableDrag === true ) {
          let startConversion = false;

          // callPOTableConversion
          if (target.classList.contains('po_table_drop_target')) {
              startConversion = true;
          }
          if(!startConversion && target.closest('.po_table_drop_target')) {
            startConversion = true;
          }

          if (startConversion) {
            // DRAG_PO_NUMBER

            if(this.hasLineItems()) {
              this.showOverrideTableConfirm = true;
            } else {
              this.prepareTableFromDropedSource();
            }

          }
          return;
        }

        let id = '';
        let td = event.target.closest('td');
        if(td) {
          id = td.dataset.id;
        } else {
          id = event.target.dataset.id;
        }

        var tr = event.target.closest('tr');
        if (!(target.tagName == 'tr' && target.className == 'droptarget') && tr && tr.className && tr.className == 'droptarget') {
          id = tr.dataset.id;
        }

        if (!id) {
          return;
        }

        this.connectWithSelectedPo(id);
      },

      connectWithSelectedPo (table_row_id: string) {
        if (this.po_line_id_for_match.length == 0 || !this.po_line_for_match) {
          return;
        }

        for(let poLineId of this.po_line_id_for_match ) {
          if(this.line_connected_items.hasOwnProperty(poLineId) && this.po_connected_items.hasOwnProperty(table_row_id)) {
            notify.error(this.$t('po_item_and_line_item_already_mapped'));
            return;
          }

          let macthedItem = {} as any;
          if(this.line_connected_items.hasOwnProperty(poLineId)) {
            macthedItem = this.line_connected_items[poLineId];
          } else if (this.po_connected_items.hasOwnProperty(table_row_id)) {
            macthedItem = this.po_connected_items[table_row_id];
          }

          if(macthedItem.table_lines || macthedItem.sub_lines) {
            if(macthedItem.table_lines && macthedItem.po_line_id != poLineId) {
              notify.error(this.$t('table_line_item_already'));
              return;
            }

            if(macthedItem.sub_lines && macthedItem.table_line_id != table_row_id) {
              notify.error(this.$t('po_line_item_already_mapped'));
              return;
            }
          }

          let poData = this.PODataObj[poLineId];

          let po_quantity = this.getPoQuantity(poData);
           if(po_quantity == 0) {
            let msg = this.$t('po_compare_quantity_error_message');
            msg = msg.replace('%%quantitycolumn%%', this.$t(this.po_quantity_column));
            notify.error(msg);
            return;
          }

          this.makeConnection(table_row_id, poData);
        }

        if(this.poConnectionData.connection_status === 'success') {
          this.saveChanges();
        } else {
          // if status is mismacth show confirmatin
          // if cancel is selected form popup, discart all the changes
          this.connectConfirmation = true;
        }
  
        this.po_line_id_for_match = [];
        this.po_line_for_match = [];
      },
  
  
      makeConnectionAndsave(item_id: string, po_data: any) {
        this.makeConnection(item_id, po_data);
        this.saveChanges();
      },
      makeConnection(item_id: string, po_data: any) {
  
        if (!item_id) {
          logError('id missing for line item, cannot connect with po')
          return;
        }
  
        this.coveredLineItem = this.lineDataObj[item_id];
        this.dragging_data = po_data;
  
  
        this.targetItem = {} as {[k: string]: any};
  
        if (!this.coveredLineItem) {
          return;
        }

        let selected_columns =  ['UNIT_PRICE','QUANTITY', 'TOTAL_AMOUNT', 'ITEM_NUMBER', 'SUPPLIER_ITEM_NUMBER', 'PURCHASE_ORDER', 'NET_AMOUNT', 'UNIT_PRICE_PER'];

        // Validate numeric fields before processing
        if (!this.validateNumericFields(po_data, this.coveredLineItem)) {
          return;
        }

        for (let [index, [column_name, column]] of Object.entries(Object.entries(this.coveredLineItem.columns))) {
  
          if (selected_columns.includes(column_name)) {
            // this.targetItem[column_name] = Object(column).formatted_value;
            this.targetItem[column_name] =  {'formatted': Object(column).formatted_value, 'value': Object(column).value};
          }
        }
        this.targetItem['UUID'] = {'formatted': this.coveredLineItem.id, 'value': this.coveredLineItem.id};
  
        if (!this.targetItem.UUID.value) {
          return;
        }
  
        this.proceedMakingConnection(item_id);
      },
      proceedMakingConnection(item_id: string) {
        if (this.is_view_readonly) {
          return;
        }
        this.connected_line_item = item_id;
        // connectNewPORecord reassigns keys on po_connected_items / line_connected_items
        // (and pushes into their sub_lines/table_lines arrays), which is reactive in Vue 3 —
        // the affected q-table cells patch in place, so no full remount is needed. Forcing a
        // remount here would reset the scroll position on large tables.
        this.connectNewPORecord();
      },
      updateUseLinesNetAmountSetting(val: boolean) {
        this.record.use_lines_net_amount_for_matched_total = val;
        // recalculations
        this.calculateMatchedTotal();
      },

  
      connectNewPORecord () {

        let po_data = {} as any;
        let connectionStatusObj = this.setPoConnectionStatus(this.targetItem, this.dragging_data);

        // For multi match item will exist else proceed with one to one matching
        if(this.po_connected_items.hasOwnProperty(this.targetItem.UUID.value)) {
  
          po_data = JSON.parse(JSON.stringify(this.po_connected_items[this.targetItem.UUID.value]));
          po_data = this.MultiPoToOneLine(po_data, connectionStatusObj);
          this.po_connected_items[this.targetItem.UUID.value] = po_data;
          
        } else if(this.line_connected_items.hasOwnProperty(this.dragging_data.id)) {
  
          po_data = JSON.parse(JSON.stringify(this.line_connected_items[this.dragging_data.id]));
          this.OnePoToMultiLine(po_data, connectionStatusObj);
          this.line_connected_items[this.dragging_data.id] = po_data;
  
        } else {
  
          po_data = this.createNewPoMatchObj(connectionStatusObj);
          this.po_connected_items[this.targetItem.UUID.value] = po_data;
        }

        this.poConnectionData = po_data;
      },
      
      createNewPoMatchObj(connectionStatusObj: any) {
        let po_data = {
          table_line_id: this.targetItem.UUID.value,
          matching_info: connectionStatusObj.matching_info,
          connection_status: connectionStatusObj.connection_status,
          connection_details: connectionStatusObj.connection_details,
          po_line_id: this.dragging_data.id,
        } as {[k: string]: any};
  
        for (let [columnName, value] of Object.entries(this.dragging_data)) {
          if (includeColumnsForPO.includes(columnName)) {
            po_data[columnName] = value === null ? '' : String(value);
          }
        }
      
        po_data['unit_code_price'] = this.getUnitCodePrice(po_data.po_line_id);
        po_data['currency_format'] = 'en_US';
        po_data['quantity'] = this.getlineDataColumn(po_data.table_line_id, 'QUANTITY');
        if(!this.isNumeric(po_data['quantity'])) {
          po_data['quantity'] = 0;
        }

        po_data['unit_price'] = this.getlineDataColumn(po_data.table_line_id, 'UNIT_PRICE');
        if(!this.isNumeric(po_data['unit_price'])) {
          po_data['unit_price'] = 0;
        }

        if (connectionStatusObj.matching_info.UNIT_PRICE.hasOwnProperty('unit_price_discounted')) {
          po_data['unit_price_discounted'] = connectionStatusObj.matching_info.UNIT_PRICE.unit_price_discounted;
        }

        if (connectionStatusObj.matching_info.UNIT_PRICE.hasOwnProperty('packet_size')) {
          po_data['packet_size'] = connectionStatusObj.matching_info.UNIT_PRICE.packet_size;
        }

        let lineUnitPrice = 0;
        let lineUnitPricePer = 1;

        if (this.lineDataObj[po_data.table_line_id].columns.UNIT_PRICE_PER && this.lineDataObj[po_data.table_line_id].columns.UNIT_PRICE_PER.value) {
          lineUnitPricePer = this.lineDataObj[po_data.table_line_id].columns.UNIT_PRICE_PER.value;
        }

        if (this.lineDataObj[po_data.table_line_id].columns.UNIT_PRICE && this.lineDataObj[po_data.table_line_id].columns.UNIT_PRICE.value) {
          lineUnitPrice = this.lineDataObj[po_data.table_line_id].columns.UNIT_PRICE.value;
        }

        const poUnitPricePer = this.dragging_data.unit_price_per ? this.dragging_data.unit_price_per : 1;

        if(lineUnitPricePer != poUnitPricePer) {
          let singleItemUnitPrice = +lineUnitPrice / +lineUnitPricePer;
          // calculate unit_price according to PO
          const unit_price = singleItemUnitPrice * +poUnitPricePer;
          po_data['unit_price'] = String(unit_price.toFixed(4));
        }
        // calculate unit_price_per according to PO
        po_data['unit_price_per'] = String(poUnitPricePer);
  
        return po_data;
      },
  
      OnePoToMultiLine(po_data: any, connectionStatusObj: any) {
  
        if(!po_data.hasOwnProperty('table_line_ids')) {
          po_data.table_line_ids = [];
          po_data.table_lines = [];
  
          // delete old line id and make array of ids for multi match
          po_data.table_line_ids.push(po_data.table_line_id);
  
          po_data.table_lines.push({'table_line_id': po_data.table_line_id, 'quantity': Number(po_data.quantity) , 'matching_info': null});
  
          delete po_data.table_line_id;
          delete po_data.matching_info;
        }
  
        po_data.table_line_ids.push(this.targetItem.UUID.value);
  
        let quantity = this.targetItem.QUANTITY ? this.targetItem.QUANTITY.value : '';
  
        po_data.table_lines.push({'table_line_id': this.targetItem.UUID.value, 'quantity': Number(quantity), 'matching_info': null});
  
        // calculate total quantity
        let existingQuantity = 0;
        for (let [index, table_line] of po_data.table_lines.entries()) {
  
          const table_line_quantity = this.lineDataObj[table_line.table_line_id].columns.QUANTITY.value;
          existingQuantity = existingQuantity + +table_line_quantity;
          
        }
  
        po_data['unit_code_price'] = this.getUnitCodePrice(po_data.po_line_id);
        po_data.quantity = existingQuantity;

        // calculate unit_price according to PO
        let avg_unit_price = this.getOnePoToManyTableLine_UnitPrice(this.dragging_data.id, this.targetItem);

        po_data['unit_price'] = String(avg_unit_price * +po_data['unit_price_per']);

        po_data.connection_details = connectionStatusObj.connection_details;
        po_data.connection_status = connectionStatusObj.connection_status; 
      },
  
      MultiPoToOneLine(po_data: any, connectionStatusObj: any): any {

        let connectionDetails = '';

        if(!po_data.hasOwnProperty('sub_lines')) {

          if(po_data.connection_details) {
            connectionDetails = po_data.connection_details;
          }
  
          let po_data_new = {
            'table_line_id': po_data.table_line_id,
            'currency_format' : po_data.currency_format,
            'connection_status': po_data.connection_status,
            'sub_lines': [] as any,
          };
          
          delete po_data.packet_size;
          delete po_data.matching_info;
          delete po_data.table_line_id;
          delete po_data.currency_format;
          delete po_data.connection_status;
          delete po_data.connection_details;
  
          // TODO
          // if (this.lineDataObj[po_data_new.table_line_id].columns.UNIT_PRICE_PER && this.lineDataObj[po_data_new.table_line_id].columns.UNIT_PRICE_PER.value) {
          //   po_data['unit_price_per'] = this.lineDataObj[po_data_new.table_line_id].columns.UNIT_PRICE_PER.value;
          // } else {
          //   po_data['unit_price_per'] = '1.00';
          // }
  
          po_data['unit_code_price'] = this.getUnitCodePrice(po_data.po_line_id);
          po_data_new.sub_lines.push(JSON.parse(JSON.stringify(po_data)));
          po_data = po_data_new;
        }
  
        let po_data_new = this.createNewPoMatchObj(connectionStatusObj);
        delete po_data_new.matching_info;
        delete po_data_new.table_line_id;
        delete po_data_new.currency_format;
        delete po_data_new.connection_status;
        delete po_data_new.connection_details;

        po_data.connection_status = connectionStatusObj.connection_status;
        po_data.connection_details = connectionStatusObj.connection_details;

        if(connectionDetails && connectionDetails.includes('item_number')) {
          po_data.connection_details += ',' + this.$t('item_number');
        } 

        po_data.sub_lines.push(po_data_new);

        this.calculateQuantityforSubLines(po_data);

        return po_data;
      },

      getAllowedDecimalForQuanities () {
        const rawValue = this.doc_attributes?.[this.po_quantities_allowed_decimals];  
        return isNaN(Number(rawValue)) ? 0 : Number(rawValue);
      },
  
      calculateQuantityforSubLines (po_data: any) {

        let totalQuantity = 0;
        let decimalPartSum = 0;
        const allowed_decimals = this.getAllowedDecimalForQuanities();

        for (let [index, sub_line] of po_data.sub_lines.entries()) {
          const po_item = this.PODataObj[sub_line.po_line_id];
          let poQuantity = this.getPoQuantity(po_item);
          totalQuantity += +poQuantity;
        }
        if (totalQuantity === 0) {
          notify.error(this.$t('total_po_quantity_is_zero'));
          return;
        }

        const lineQuantity = this.getlineDataColumn(po_data.table_line_id, 'QUANTITY');

        // split the line quantity and update the PO matching object
        for (let [index, sub_line] of po_data.sub_lines.entries()) {

          const po_item = this.PODataObj[sub_line.po_line_id];
          let poQuantity = this.getPoQuantity(po_item);
          const calculatedQty = (poQuantity / totalQuantity) * Number(lineQuantity);

          const safeDecimals = Number(allowed_decimals) || 4;
          sub_line.quantity = String(calculatedQty.toFixed(safeDecimals));
        }
        
      },

  
      getUnitCodePrice (po_line_id:string) {
        let unit_code_price = '';
  
        if (!this.PODataObj.hasOwnProperty(po_line_id)) {
          return unit_code_price;
        }
  
        
        if (this.PODataObj[po_line_id].hasOwnProperty('unit_code_price')) {
          unit_code_price = this.PODataObj[po_line_id].unit_code_price;
        }
        else if (this.PODataObj[po_line_id].hasOwnProperty('unit_code')) {
          unit_code_price = this.PODataObj[po_line_id].unit_code;
        }
  
        return unit_code_price;
      },
  

      async getLineItemQuantityColumn () {
        let quantity_col = 'quantity';
        let column_name = this.apiData.doc_type + '_QUANTITY_COL';
        const prefer_qty_column = await this.getSetting(column_name);
        if (prefer_qty_column !== undefined && prefer_qty_column !== '') {
          quantity_col = prefer_qty_column;
        }

        return quantity_col;
      },
  
      matchPoNumber (lineItem: any, POItem: any) {
        let match = true;
  
        if(this.isLineColumnAvailable (lineItem, 'PURCHASE_ORDER') && POItem.hasOwnProperty('purchase_order_number')) {
          const line_purchaseOrder = lineItem.PURCHASE_ORDER.value;
          const po_purchase_order_number = POItem.purchase_order_number;
  
          if(line_purchaseOrder && po_purchase_order_number && this.notEqual(line_purchaseOrder, po_purchase_order_number)) {
            this.misMatchedList.push(this.$t('purchase_order_number')) ;
            match = false;
          }
  
        } else if (this.isLineColumnAvailable (lineItem, 'PURCHASE_ORDER')) {
          this.misMatchedList.push(this.$t('purchase_order_number')) ;
          match = false;
        }
  
        return match;
      },
  
      matchItemNumber (lineItem: any, POItem: any) {
        const result = { is_matched : true} as dynamicObj;
        let match = false;

        const isSupplierItemNumber = this.isLineColumnAvailable (lineItem, 'SUPPLIER_ITEM_NUMBER');
        const isItemNumber = this.isLineColumnAvailable (lineItem, 'ITEM_NUMBER');
        if (!isSupplierItemNumber && !isItemNumber) {
          result['is_matched'] = match;
          this.misMatchedList.push(this.$t('supplier_number') + ' / ' + this.$t('item_number')) ;
          return result;
        }

        const po_item_id = removeSpacesAndUnderscore(POItem.item_id || '').toLowerCase();
        const line_item_number = removeSpacesAndUnderscore(isItemNumber && lineItem.ITEM_NUMBER.value || '').toLowerCase();
        const po_supplier_item_id = removeSpacesAndUnderscore(POItem.supplier_item_id || '').toLowerCase();
        const line_supplier_item_number = removeSpacesAndUnderscore(isSupplierItemNumber ? lineItem.SUPPLIER_ITEM_NUMBER.value : '').toLowerCase();

        result['actual'] = line_item_number;
        result['expected'] = po_item_id;

        if(line_item_number && po_item_id && !this.notEqual(line_item_number, po_item_id)) {
          match = true;
        
        } else if(line_supplier_item_number && po_supplier_item_id && !this.notEqual(line_supplier_item_number, po_supplier_item_id)) {
          result['actual'] = line_supplier_item_number;
          result['expected'] = po_supplier_item_id;
          match = true;
        
        } else if(line_supplier_item_number && po_item_id && !this.notEqual(line_supplier_item_number, po_item_id)) {
          result['actual'] = line_supplier_item_number;
          result['expected'] = po_item_id;
          match = true;
        
        } else if(line_item_number && po_supplier_item_id && !this.notEqual(line_item_number, po_supplier_item_id)) {
          result['actual'] = line_item_number;
          result['expected'] = po_supplier_item_id;
          match = true;
        
        } else if(this.po_supplier_item_numbers[po_item_id] && this.po_supplier_item_numbers[po_item_id][line_item_number]) {
          match = true;

        } else {
          match = false;
          this.misMatchedList.push(this.$t('supplier_number') + ' / ' + this.$t('item_number')) ;
        }

        if(!result['actual']){
          result['actual'] = 'N/A';
          match = false;
        }
        if(!result['expected']){
          result['expected'] = 'N/A';
          match = false;
        }
        result['is_matched'] = match;
        return result;
      },
  
      setPoConnectionStatus (lineItem: any, POItem: any) {
  
        let matching_info = {QUANTITY: {}, UNIT_PRICE: {}, PACKET_MATCH: {}, ITEM_NUMBER: {}};
        this.misMatchedList = [];
        let connection_status = 'success';
  
        const line_ITEM_NUMBER = lineItem.ITEM_NUMBER ? lineItem.ITEM_NUMBER.value : '';
        let supplierItemNumber = lineItem.SUPPLIER_ITEM_NUMBER ? lineItem.SUPPLIER_ITEM_NUMBER.value : '';
        let itemNumber = this.cleanItemNumber(line_ITEM_NUMBER);
        supplierItemNumber = this.cleanItemNumber(supplierItemNumber);
        fillToleranceModel(itemNumber, supplierItemNumber);

        const extraColumnsObj: any = this.checkTableExtraColumnsStatus(lineItem, POItem);

        if (Object.keys(extraColumnsObj.matching_info).length >= 0) {

          if (!extraColumnsObj.match) {
              connection_status = 'mismatch';
          }
          Object.assign(matching_info, extraColumnsObj.matching_info);
        }

        // for multimatch skip this validation
        if(!this.po_connected_items.hasOwnProperty(this.targetItem.UUID.value) && !this.line_connected_items.hasOwnProperty(POItem.id))  {

          let is_item_number_match = true;
          // also skip if item number matching is off
          if(this.user_settings[CONSTANTS.PO_MATCH_IGNORE_ITEM_NUMBER_FOR_SINGLE_LINE_MATCH] == false) {
            const matchItemNumber = this.matchItemNumber(lineItem, POItem);
            is_item_number_match = matchItemNumber.is_matched;
            if (!is_item_number_match) {
              connection_status = 'mismatch';
              matching_info.ITEM_NUMBER = matchItemNumber;
            }
          }

          if (is_item_number_match && this.apiData.doc_type != CONSTANTS.DELIVERY_NOTE) {
            const packetMatchStatus: any = this.matchByPacket(lineItem, POItem);
            const packet_matching_info = packetMatchStatus.matching_info;
            if (packetMatchStatus.is_matched && packet_matching_info && packet_matching_info.UNIT_PRICE && (packet_matching_info.UNIT_PRICE.packet_size >= 10 || packet_matching_info.UNIT_PRICE.packet_size <= 0.1 )) {
              matching_info.UNIT_PRICE = packet_matching_info;
              if (!packetMatchStatus.is_perfect_match){
                this.misMatchedList.push(this.$t('unit_price')) ;
                this.misMatchedProperties = this.misMatchedList.join(', ');
                connection_status = 'mismatch';
              }
              const responseObj = {
                matching_info: packet_matching_info,
                connection_status : connection_status,
                connection_details : this.misMatchedProperties,
              }
              return responseObj;
            }
          }
        }

        const quantityStatusObj: any = this.checkQuantityStatus(lineItem, POItem);
        matching_info.QUANTITY = quantityStatusObj.match_obj;
        if (!quantityStatusObj.match) {
          connection_status = 'mismatch';
        }
  
        // for DELIVERY_NOTE skip unit price checking 
        if(this.apiData.doc_type != CONSTANTS.DELIVERY_NOTE) {
          const unitPriceStatusObj: any = this.checkUnitPriceStatus(lineItem, POItem);
          if (!unitPriceStatusObj.match) {
            connection_status = 'mismatch';
          }
          matching_info.UNIT_PRICE = unitPriceStatusObj.match_obj;
        }
  
        this.misMatchedProperties = this.misMatchedList.join(', ');
        
        const responseObj = {
          matching_info: matching_info,
          connection_status : connection_status,
          connection_details : this.misMatchedProperties,
        }
        return responseObj;
      },

      isWholeNumber(num: any) {
        return Number.isInteger(num);
      },      
      matchByPacket (lineItem: any, POItem: any) {
        const po_line_quantity = this.getPoQuantity(POItem);
        const table_line_quantity = this.getLineQuantity(lineItem);
        let match = false;
        let is_inverse_multiplier = false;
        let multiplier = 1;
        let matching_info = {UNIT_PRICE: {}, QUANTITY: {}} as dynamicObj;

        if (isUndefinedOrNull(po_line_quantity) || isUndefinedOrNull(table_line_quantity)){
          return {match, matching_info: {}};
        }

        multiplier = po_line_quantity / table_line_quantity
        if (multiplier < 1) {
          is_inverse_multiplier = true;
          multiplier = table_line_quantity / po_line_quantity;
        }
        if (this.isWholeNumber(multiplier) === false) { 
          return {match, matching_info: {}};
        }

        if (is_inverse_multiplier) {
          multiplier = 1 / multiplier;
        }

        const po_unit_price = this.getPoUnitPrice(POItem);
        const line_unit_price = this.getLineUnitPrice(lineItem);
        const actual_unit_price = line_unit_price / multiplier;
 
        const isMatchTypePercent = this.toleranceModel['unit_price_tolerance_type'] == this.percent ? true : false;
        const is_unit_price_matched = !(this.matchValues(actual_unit_price, po_unit_price , this.toleranceModel.unit_price_tolerance, isMatchTypePercent, 'UNIT_PRICE'));
 
        const is_perfect_match = is_unit_price_matched
        const is_matched = is_perfect_match || multiplier === 0.001

        matching_info.QUANTITY = this.getMatchingInfo(
          true,
          po_line_quantity,
          table_line_quantity,
          0,
          false,
          {packet_size: multiplier}
        );

        matching_info.UNIT_PRICE = this.getMatchingInfo(
          is_perfect_match,
          po_unit_price,
          actual_unit_price,
          this.toleranceModel.unit_price_tolerance,
          isMatchTypePercent,
          {packet_size: multiplier}
        );
 
        return {is_matched, is_perfect_match, matching_info};
 
      },

      checkUnitPriceStatus(lineItem: any, POItem: any) {
        try {
          let match = true;
          let po_final_unit_price = this.getPoUnitPrice(POItem);
          let line_final_unit_price = this.getLineUnitPrice(lineItem);

          // if multi invoice calculate quantity
          if(this.po_connected_items.hasOwnProperty(this.targetItem.UUID.value)) {
            let po_quantity = this.getPoQuantity(POItem);
  
            po_final_unit_price = this.getManyPoToOneLine_UnitPrice(this.targetItem.UUID.value, Number(po_final_unit_price), po_quantity);
  
          } else if(this.line_connected_items.hasOwnProperty(POItem.id)) {
  
            
            line_final_unit_price = this.getOnePoToManyTableLine_UnitPrice(POItem.id, lineItem);
          }
          let isMatchTypePercent = this.toleranceModel['unit_price_tolerance_type'] == this.percent ? true : false;

          let matchStatus = this.matchValues(po_final_unit_price, line_final_unit_price, this.toleranceModel.unit_price_tolerance, isMatchTypePercent, 'UNIT_PRICE');
          
          if(matchStatus) {
            match = false;
            this.misMatchedList.push(this.$t('unit_price')) ;
          }
          const match_obj = this.getMatchingInfo(
            !matchStatus,
            po_final_unit_price,
            line_final_unit_price,
            this.toleranceModel.unit_price_tolerance,
            isMatchTypePercent,
        );
          return {match, match_obj};
          
        } catch (error) {
          notify.error(this.$t('check_unit_price_column'));
          logError('error', error);
        }
        
      },
      checkTableExtraColumnsStatus(lineItem: any, POItem: any) {

        let matching_info: any = {};
        // let match_obj = {};
        let match = true;

        const TABLE_EXTRA_COLUMNS_KEY = CONSTANTS.TABLE_EXTRA_COLUMNS_ + this.apiData.doc_type;
        const TABLE_EXTRA_COLUMNS = this.user_settings[TABLE_EXTRA_COLUMNS_KEY];

        if(!TABLE_EXTRA_COLUMNS ) {
          return {match, matching_info};
        }
        
        const tableExtraColumns = JSON.parse(TABLE_EXTRA_COLUMNS);

        if(!tableExtraColumns || tableExtraColumns.length == 0 ) {
          return {match, matching_info};
        }

        for(let extraColumns of tableExtraColumns) {

          const lineColumnName = extraColumns.line_column ? extraColumns.line_column : this.PO_TABLE_MAP[extraColumns.po_column];
          const poColumnName = extraColumns.po_column ? extraColumns.po_column : this.PO_TABLE_MAP_REVERSE[extraColumns.line_column];

          if(!lineColumnName || !poColumnName) {
            continue; 
          }

          const lineValue =  this.getlineDataColumn(lineItem.UUID.value, lineColumnName);
          const poValue =  POItem[poColumnName];

          if(lineColumnName.toLowerCase().includes('date')) {
            const promised_delivery_date = this.formatDateWithPattern(lineValue, dateFormates.date_only);
            const requested_ship_date = this.formatDateWithPattern(poValue, dateFormates.date_only);
  
            if(this.dateDifferenceInDays(promised_delivery_date, requested_ship_date) != 0) {
              match = false;
              this.misMatchedList.push(this.$t(lineColumnName));
            }
            matching_info[lineColumnName] = this.getMatchingInfoForString(match, requested_ship_date, promised_delivery_date);
            
          } else if(this.isNumeric(lineValue) && poValue && this.isNumeric(poValue)) {
            match = !(this.matchValues(poValue, lineValue, 0, false, lineColumnName));
            matching_info[lineColumnName] = this.getMatchingInfo(match, poValue, lineValue,  0, false);
            if(!match) {
              this.misMatchedList.push(this.$t(lineColumnName));
            } 
          } else {
            match = (lineValue === poValue) ? true : false;
            if(!match) {
              this.misMatchedList.push(this.$t(lineColumnName));
            }
            matching_info[lineColumnName] = this.getMatchingInfoForString(match, poValue, lineValue);
          }
        }

        return {match, matching_info};

      },
      getManyPoToOneLine_UnitPrice(lineId: string, line_unitPrice: number, line_quantity: number) {
  
        let poData = this.po_connected_items[lineId];
        let totalQuanty = 0;
        let avgUnitPrice = 0;
  
        // check if one po is mapped against single line items
        if(poData.hasOwnProperty('po_line_id')) {
          const poItem = this.PODataObj[poData.po_line_id];
          const poQuantity = this.getPoQuantity(poItem);
          const poUnitPrice = this.getPoUnitPrice(poItem);

          avgUnitPrice = Number(poUnitPrice) * Number(poQuantity);
          totalQuanty = totalQuanty + Number(poQuantity);
        }
  
        // check if one line is mapped against multiplal po items
        if(poData.hasOwnProperty('sub_lines')) {
          for (let [index, sub_line] of poData.sub_lines.entries()) {
            avgUnitPrice = avgUnitPrice + (Number(sub_line.unit_price) * Number(sub_line.quantity));
            totalQuanty = totalQuanty + Number(sub_line.quantity);
          }
        }
  
        totalQuanty = totalQuanty + Number(line_quantity);
        avgUnitPrice = avgUnitPrice + (line_quantity * line_unitPrice);
        avgUnitPrice = avgUnitPrice / totalQuanty;
        if (isNaN(avgUnitPrice)) {
          avgUnitPrice = 0;
        }
  
        return +(Number(avgUnitPrice).toFixed(4));
      },
  
      getOnePoToManyTableLine_UnitPrice(poId: string, currentlineItem: any)  {

        const line_quantity = (this.getLineQuantity(currentlineItem));
        let line_unitPrice = Number(this.getLineUnitPrice(currentlineItem));
  
        let lineData = this.line_connected_items[poId];
        let totalQuanty = 0;
        let avgUnitPrice = 0;
  
        // check if one line is mapped against single po items
        if(lineData.hasOwnProperty('table_line_id')) {

          const lineItem = this.lineDataObj[lineData.table_line_id]['columns'] ;
          // existingQuantity = +lineItem.QUANTITY.value;
          let unitPrice = Number(this.getLineUnitPrice(currentlineItem, lineData.table_line_id));
          avgUnitPrice = Number(lineItem.QUANTITY.value) * Number(unitPrice);
          totalQuanty = totalQuanty + Number(lineItem.QUANTITY.value);
        }
  
        // check if one po is mapped against multiplal line items
        if(lineData.hasOwnProperty('table_line_ids')) {
          for (let [index, table_line] of lineData.table_lines.entries()) {
  
            const table_line_quantity = +this.getlineDataColumn(table_line.table_line_id, 'QUANTITY');
            const lineItem = this.lineDataObj[table_line.table_line_id].columns ;

            let unitPrice = Number(this.getLineUnitPrice(currentlineItem, table_line.table_line_id));
  
            avgUnitPrice = avgUnitPrice + (table_line_quantity * unitPrice);
            totalQuanty = totalQuanty + table_line_quantity;
          }
        }
  
        totalQuanty = totalQuanty + Number(line_quantity);
        avgUnitPrice = avgUnitPrice + (line_quantity * line_unitPrice);
  
        avgUnitPrice = avgUnitPrice / totalQuanty;
  
        return +(Number(avgUnitPrice).toFixed(4));
  
      },
  
  
      checkQuantityStatus(lineItem: any, POItem: any) {
        try {
          let match = true;
          let po_quantity = this.getPoQuantity(POItem);
          let line_quantity = this.getLineQuantity(lineItem);

          // if multi invoice calculate quantity
          if(this.po_connected_items.hasOwnProperty(this.targetItem.UUID.value)) {
            // manypo_to_oneline
            po_quantity = this.getManyPoToOneLine_Quantity(this.targetItem.UUID.value, Number(po_quantity), Number(line_quantity));
          } else if(this.line_connected_items.hasOwnProperty(POItem.id)) {
            // onepo-to-manyline
            line_quantity = this.getOnePoToManyLine_Quantity(POItem.id, Number(line_quantity));
          }
          
          let isMatchTypePercent = this.toleranceModel['quantity_tolerance_type'] == this.percent ? true : false;
          let matchStatus = this.matchValues(po_quantity, line_quantity, this.toleranceModel.quantity_tolerance, isMatchTypePercent, 'QUANTITY');
          if(matchStatus) {
            match = false;
            this.misMatchedList.push(this.$t('quantity')) ;
          }
  
          const match_obj = this.getMatchingInfo(!matchStatus, po_quantity, line_quantity, this.toleranceModel.quantity_tolerance, isMatchTypePercent);
          return {match, match_obj};
        } catch (error) {
          notify.error(this.$t('check_quantity_column'));
          logError('error', error);
        }
        
      },

      getLineQuantity(lineItem: any) {
        let line_quantity = this.isLineColumnAvailable (lineItem, 'QUANTITY') && lineItem.QUANTITY ? lineItem.QUANTITY.value : 0;
        if(!this.isNumeric(line_quantity)) {
          line_quantity = 0;
        }
        return +line_quantity
      },

      getLineUnitPrice(lineItem: any, line_id = '') {
        const line_unit_price = this.isLineColumnAvailable (lineItem, 'UNIT_PRICE') && lineItem.UNIT_PRICE ? lineItem.UNIT_PRICE.value : 0;

        const table_line_id = lineItem.UUID && lineItem.UUID.value ? lineItem.UUID.value : line_id;
        let unit_price = this.getDiscountedUnitPrice({table_line_id: table_line_id}, line_unit_price);
        let line_unit_price_per = 1;

        if (this.isLineColumnAvailable (lineItem, 'UNIT_PRICE_PER') && lineItem.UNIT_PRICE_PER.value) {
          line_unit_price_per = lineItem.UNIT_PRICE_PER.value;
        }

        let line_final_unit_price = unit_price / line_unit_price_per;
        line_final_unit_price = Math.round(line_final_unit_price * 10000) / 10000;
        return +line_final_unit_price;
      },
  

  
      //  many po to single line
      getManyPoToOneLine_Quantity(lineId: string, new_quantity: number, line_quantity: number) {

        let poData = this.po_connected_items[lineId];
        let existingQuantity = 0;
  
        // check if one po is mapped against single line items
        if(poData.hasOwnProperty('po_line_id')) {
          const po_item = this.PODataObj[poData.po_line_id];
          let po_quantity = this.getPoQuantity(po_item);
          existingQuantity = +po_quantity;
        }
  
        // check if one line is mapped against multiplal po items
        if(poData.hasOwnProperty('sub_lines')) {
          for (let [index, sub_line] of poData.sub_lines.entries()) {
            const po_item = this.PODataObj[sub_line.po_line_id];
            let po_quantity = this.getPoQuantity(po_item);
            existingQuantity = existingQuantity + +po_quantity;
          }
        }

        return existingQuantity + new_quantity;
      },
  
      //  one po to many line
      getOnePoToManyLine_Quantity(poId: string, new_quantity: number) {
        let lineData = this.line_connected_items[poId];
        let existingQuantity = 0;
  
        // check if one line is mapped against single po items
        if(lineData.hasOwnProperty('table_line_id')) {
          const lineItem = this.lineDataObj[lineData.table_line_id]['columns'] ;
          existingQuantity = +lineItem.QUANTITY.value;
        }
  
        // check if one po is mapped against multiplal line items
        if(lineData.hasOwnProperty('table_line_ids')) {
          for (let [index, table_line] of lineData.table_lines.entries()) {
            const line_quantity = this.getlineDataColumn(table_line.table_line_id, 'QUANTITY');
            existingQuantity = existingQuantity + +line_quantity;
          }
        }
  
        return existingQuantity + new_quantity;
  
      },

      getlineDataColumn (table_line_id:string, column_name: string) {
        try {
           
          return this.getlineColumnValue(table_line_id, column_name);
        } catch (error) {
          notify.error('Column '+column_name+' for matching');
          logError('Column '+column_name+' is missing in lineDataObj');
        }
        return '';
      },
  
      getMatchingInfo(isMatched: boolean, expected: number, actual: number, tolerance: number, isMatchTypePercent: boolean, extra_info: dynamicObj = {}) {
        if(isMatchTypePercent) {
          tolerance = (+tolerance / 100 ) * actual;
        }
  
        const match_obj = {
          'is_matched': isMatched,
          'expected': expected,
          'actual': actual,
          'tolerance': tolerance
        };

        if (Object.keys(extra_info).length > 0) {
          Object.assign(match_obj, extra_info);
        }
  
        return match_obj;
      },

      getMatchingInfoForString(isMatched: boolean, expected: string, actual: string) {

        const match_obj = {
          'is_matched': isMatched,
          'expected': expected,
          'actual': actual
        };
  
        return match_obj;
      },

      notEqual (value1:any, value2:any) {
        // remove spaces and convert to lower cases
        value1 = value1.toString().replace(/\s/g, '').toLowerCase();
        value2 = value2.toString().replace(/\s/g, '').toLowerCase();
        return value1 != value2;
      },
  
      notEqualAmount (value1:any, value2:any) {
        // round to 4 decimal places
        value1 = Number(value1).toFixed(4);
        value2 = Number(value2).toFixed(4);
        return value1 != value2;
      },
  
      useToleranceForMatch (value1:any, value2:any, tolerance: any, isMatchTypePercent: boolean) {
        let difference = value1 - value2;
        difference = Number(Math.abs(difference).toFixed(4));
        tolerance =  Number(Number(tolerance).toFixed(4));

        if(difference == 0) {
          return false;
        }
  
        if(isMatchTypePercent) {
          if(tolerance > 100 || tolerance < 0) {
            notify.error(this.$t('TOLERANCE_RANGE'));
            return true;
          }
          tolerance = (tolerance / 100 ) * value1;
        }

        return tolerance < difference;
      },

      matchValues (value1:any, value2:any, tolerance: any, isMatchTypePercent: boolean, fieldName?: string) {
        // Convert both input values to numbers
            let num1 = Number(value1);
            let num2 = Number(value2);

          // Check if either conversion resulted in NaN (e.g., invalid string input)
          // This usually indicates an issue with the backend data
          if (Number.isNaN(num1) || Number.isNaN(num2)) {
             // Show an error toast to inform the user
             // Returning true to indicate a mismatch
              const fieldInfo = fieldName ? ` (Field: ${this.$t(fieldName)})` : '';
              notify.error(`Invalid input: one of the values is not a valid number. ${fieldInfo}`);
              return true;
          }

          // Round both numeric values to 4 decimal places for comparison
         // Convert them back to strings after rounding
          value1 = num1.toFixed(4);
          value2 = num2.toFixed(4);

        if(this.doc_attributes[this.custom_range_for_po_tolerance]) {
          return this.useToleranceForMatch(Number(value1), Number(value2), tolerance, isMatchTypePercent);
        }
        
        return value1 != value2;
      },
      saveChanges() {
        this.dispatchConnectionSuccessEvent(this.poConnectionData);
      },
      removeExistingAndConnectNewPO () {
        this.confirmDialog = false;
        let connection_info = this.po_connected_items.hasOwnProperty(this.connected_line_item) ? this.po_connected_items[this.connected_line_item] : {};
        this.dispatchConnectionRemoveEvent(connection_info, false);
        delete this.po_connected_items[this.connected_line_item];
        this.connectNewPORecord();
        this.saveChanges();
      },
      removePOConnection (id: string, isPoId: boolean) {
        this.blockProcessing = true;
        this.dispatchConnectionRemoveEvent(id, isPoId);
          setTimeout(() => {
            this.blockProcessing = false;
          }, 1000);
      },

      validateNumericFields(poItem: any, lineItem: any): boolean {
        try {
          const po_columns_to_validate = ['unit_price', 'unit_price_calculated', 'unit_price_per', 'quantity', 'invoice_open_quantity', 'received_quantity'];
          const line_columns_to_validate = ['QUANTITY', 'UNIT_PRICE', 'UNIT_PRICE_PER', 'TOTAL_AMOUNT', 'NET_AMOUNT', 'DISCOUNT'];

          // Validate PO Item numeric fields
          if (poItem) {
            for (const fieldName of po_columns_to_validate) {
              const fieldValue = poItem[fieldName];
              if (fieldValue !== null && fieldValue !== undefined && fieldValue !== '') {
                const numValue = Number(fieldValue);
                if (isNaN(numValue)) {
                  const translatedFieldName = this.$t(fieldName);
                  notify.error('Invalid input: one of the values is not a valid number:' + translatedFieldName);
                  return false;
                }
              }
            }
          }

          // Validate Line Item numeric fields
          if (lineItem && lineItem.columns) {
            for (const fieldName of line_columns_to_validate) {
              if (lineItem.columns[fieldName]) {
                const fieldValue = lineItem.columns[fieldName].value;
                if (fieldValue !== null && fieldValue !== undefined && fieldValue !== '') {
                  const numValue = Number(fieldValue);
                  if (isNaN(numValue)) {
                    const translatedFieldName = this.$t(fieldName);
                    notify.error('Invalid input: one of the values is not a valid number:' + translatedFieldName);
                    return false;
                  }
                }
              }
            }
          }

          return true;
        } catch (error) {
          notify.error('Invalid input: one of the values is not a valid number');
          return false;
        }
      },
    },
    setup() {
      const el = ref(null)
      let data : any = [];
      let model =  {} as  {[k: string]: any};
  
      const doc_store = useDocumentStore();
      const { record, doctype, remove_unmapped_columns, has_ai_table } = storeToRefs(doc_store);
      const { removeCache, isAI_TableExit } = doc_store;

      const doc_tables_store = usePOLineItemsStore();
      const { tableColumns, lineItemLayout, layoutExtraColumns } = storeToRefs(doc_tables_store);
      const { 
        prepareTableLayoutObj,
        getTableColumns,
        setFormatOptions,
        isColumnNameValid,
        isLineColumnAvailable
      } = doc_tables_store;

      const master_data_lookup = useMasterDataLookupStore();
      const { prepareCostingElementDictionary } = master_data_lookup;
      const { costingElementDictionary } = storeToRefs(master_data_lookup);
      // Shared height persist/restore; applyStoredHeight runs after rows render
      // (see lineItemDataLoaded) instead of from an updated() hook.
      const { applyStoredHeight, initResizeObserver } = useTableHeightResize(el, {
        settingKey: 'LINE_ITEM_TABLE_SETTING',
        minHeight: 200
      });
      initResizeObserver();
      const po_match_store = usePoMatchStore();
      const {
        total_net_amount,
        auto_match_alert,
        is_view_readonly,
        po_connected_items,
        line_connected_items,
        PODataObj,
        pending_amount,
        charges_amount,
        matched_total_amount,
        amount_error,
        toleranceModel,
        lineDataObj,
        po_line_id_for_match,
        po_line_for_match,
        po_quantity_column,
        isChargesModuleEnabled,
        po_supplier_item_numbers,
        PO_TABLE_MAP,
        PO_TABLE_MAP_REVERSE,
      } = storeToRefs(po_match_store);
      const { getDiscountedUnitPrice, initToleranceModel, calculateMatchedTotal, setTotallineItem, getlineColumnValue, getSavedColumns, getColumns, getPoUnitPrice, getPoQuantity, prepareLineMapping, setToleranceForItem, getToleranceForItem, hasToleranceForItem } = po_match_store;

      const doc_attribute_store = useDocAttributesStore();
      const { model:doc_attributes } = storeToRefs(doc_attribute_store);
      const settings_store = useSettingStore();
      const { user_settings,loading_settings } = storeToRefs(settings_store);
      const { getSetting, updateSetting } = settings_store;
     
      return {
        applyStoredHeight,
        prepareTableLayoutObj,
        getTableColumns,
        setFormatOptions,
        isColumnNameValid,
        isLineColumnAvailable,
        getDiscountedUnitPrice,
        tableColumns,
        lineItemLayout,
        layoutExtraColumns,

        getPoQuantity,
        getPoUnitPrice,
        setTotallineItem,
        getlineColumnValue,
        getSavedColumns,
        getColumns,
        prepareCostingElementDictionary,
        costingElementDictionary,
        po_supplier_item_numbers,
        isChargesModuleEnabled,
        po_quantity_column,
        user_settings,loading_settings,
        getSetting,
        updateSetting,
        remove_unmapped_columns,
        has_ai_table,
        ai_table_setting_flag: ref(false),

        po_line_id_for_match,
        po_line_for_match,
        is_view_readonly,
        auto_match_alert,
        po_connected_items,
        line_connected_items,
        PODataObj,
        record,
        doctype,
        amount_error,
        doc_attributes,
        toleranceModel,
        pending_amount,
        charges_amount,
        total_net_amount,
        matched_total_amount,
        setToleranceForItem,
        getToleranceForItem,
        hasToleranceForItem,
        el,
        removeCache,
        isAI_TableExit,
        initToleranceModel,
        is_ai_table: ref(false),
        poEditRestrictDialog: ref(false),
        poEditRestrictMessage: ref(''),
        lineItemsloading: ref(true),
        tableRows: ref(data),
        apiData: ref(data),
        table_name: ref(''),
        lineDataObj,
        targetItem: ref(model),
        connectConfirmation: ref(false),
        showOverrideTableConfirm: ref(false),
        poConnectionData: ref({} as dynamicObj),
  
        tableObj: ref({} as dynamicObj),
        calculateMatchedTotal,
        startY: 0,
        isResizing: false,

        pagination: ref({
          sortBy: '', // Default Sorting Column
          descending: false // Sorting Direction
        }),

        PO_TABLE_MAP,
        PO_TABLE_MAP_REVERSE,
        prepareLineMapping,
      };
    }
  });
  </script>
  
