      poElements: [] as any,
      warning_alert: {} as any,
      dragableItems: [] as any,
      visible_columns: [] as any,
      showAdanceFilter: ref(false),
      currentPoElementIndex: ref(0),
      debounceAutoSaveFunc: {} as any,
      allowedDoctypes: allowedDocTypes,
      percent: CONSTANTS.percent,
      po_table_columns: po_table_columns,
      charges_table_extraction: charges_table_extraction,
      routeUrl: ref(''),
      poLoading: ref(false),
      poToRefresh: ref(''),
      dynamicWidth: ref(0),
      isSavePending: ref(false),
      imageFieldSplitter: ref(76),
      showConfirmSyncDlg: ref(false),
      auto_update_po_data: ref(false),
      showRouteLeaveConfirmation: ref(false),
    };
  },
  mounted() {
    this.docId = this.$route.params.id as string;
    this.record = [];
    this.init();
    this.initFilterModel();
    document.addEventListener('po_connection_success', this.lineItemConnected);
    document.addEventListener('po_connection_remove',this.removeLineItemPO);
    document.addEventListener('table_drag_mode_flag_update',this.TableDragModeHandler);
    document.addEventListener('update_table_data', this.updateTableDataForSave);
    document.addEventListener('delete_table_line', this.deleteTableLine);
    document.addEventListener('convert_pline_to_ltable',this.triggerTableConversion);
    document.addEventListener('keydown', this.keyDownEvent);

    document.addEventListener('trigger_auto_match', this.triggerAutoMatch);
    document.addEventListener('line_items_loaded', this.lineItemsLoaded);
    document.addEventListener('po-table-column-drop', this.onDragColumn);

    this.debounceAutoSaveFunc = debounce(() => {
      this.saveDataOnChanges();
    }, 1000);

    this.poElements = document.getElementsByClassName('po_iterateable_item');

    (<any>window).vpo = this;
  },

  unmounted: async function () {
    document.removeEventListener('po_connection_success',this.lineItemConnected);
    document.removeEventListener('po_connection_remove',this.removeLineItemPO);
    document.removeEventListener('keydown', this.keyDownEvent);
    document.removeEventListener('table_drag_mode_flag_update', this.TableDragModeHandler);
    document.removeEventListener('update_table_data',this.updateTableDataForSave);
    document.removeEventListener('delete_table_line', this.deleteTableLine);
    document.removeEventListener('convert_pline_to_ltable',this.triggerTableConversion);
    document.removeEventListener('trigger_auto_match', this.triggerAutoMatch);
    document.removeEventListener('line_items_loaded', this.lineItemsLoaded);
    document.removeEventListener('po-table-column-drop', this.onDragColumn);
    this.resetPoMatchStore();
    await this.releaseDocLock({doc_id: this.docId})
  },
  computed: {
    hasPoItems: function () {
      return this.po_items && Object.keys(this.po_items).length !== 0;
    },
  },
  methods: {
    async init() {
      try {

        this.first_time_view_render = true;
        this.processing = true;
        this.error = false;
        // settings sould be loaded before other stuff
        await this.initUserSettings();
        this.isDocForExtTraining();
        this.fetch_po_items = false;
        if (this.ext_table_train === true) {
          await this.getExtAppPODocumentByID(this.docId);
        } else {

          await this.getDocumentById(this.docId);
          if (!this.record || Object.keys(this.record).length === 0 || this.record.success === false) {
            return;
          }

          this.handleReadOnly();
        }
        this.initDragableList();

        this.handleReadOnlyAlert();
        this.imageObjStr = JSON.stringify(this.record.images);
        try {
          await this.getPOColumns();
        } catch (err) {
          notify.error(this.$t('PO_COLUMNS_API_ERROR'));
          logError(err);
        }

        this.ShowStaticPO();
        this.getFieldValues();
        await this.initPage();
        this.processAttributes();
        this.setPoQuantityColumn();
        this.calculateMatchedTotal();

      } catch (err: any) {
        logError(err);
        if (
          err != null &&
          typeof err == 'object' &&
          err.hasOwnProperty('message')
        ) {
          notify.error(err.message);
          return;
        }
        notify.error(
          'Error while displaying Page. Please reload again or contact admistrator'
        );

      } finally {
        this.processing = false;
      }

    },
    async processAttributes() {
      if (isUndefinedOrNull(this.po_items) || objLen(this.po_items) == 0 || this.is_view_readonly) {
        return;
      }
      await this.fetchAttributes(this.doctype);

      if(this.docAttributesModel[CONSTANTS.auto_check_for_po_update]) {
        await this.checkForPoUpdates();

        if(!this.execute_auto_export && this.auto_update_po_data) {
          await this.autoPoMatch();
        }
      }

      await this.checkAutoExport(); // Then check for auto export

    },
    async checkForPoUpdates() {

      let syncPoMatchedRequired = false;

      let poNumbers: string[] = [];

      for (let [key, item] of Object.entries(this.po_items)) {
        poNumbers.push(key);
      }

      let poItemsUpdates = (await this.getPOitems(poNumbers.join(',')));

      if(!poItemsUpdates || poItemsUpdates.length == 0) {
        return;
      }

      let poItemsDictionary = {} as dynamicObj;
      let tempDictionary = {} as dynamicObj;

      for(let poItem of poItemsUpdates) {

        if(!poItemsDictionary[poItem.purchase_order_number]) {
          tempDictionary[poItem.purchase_order_number] = {} as dynamicObj;
          poItemsDictionary[poItem.purchase_order_number] = [] as any;
        }

        poItemsDictionary[poItem.purchase_order_number].push(poItem);
        tempDictionary[poItem.purchase_order_number][this.getItemUniqueKey(poItem)] = poItem;
      }

      for (let [key, poItem] of Object.entries(this.po_items)) {

        // if both element lenght is different then there is some update
        if(poItem.length != poItemsDictionary[key].length) {
          this.updatePOData(key, poItemsDictionary[key]);
          continue;
        }
        
        for (let item of poItem) {
          const newPoItem = tempDictionary[key][this.getItemUniqueKey(item)];
          if(item.updated_on != newPoItem.updated_on || item.unit_price_calculated != newPoItem.unit_price_calculated) {
            this.updatePOData(key, poItemsDictionary[key]);
            break;
          }

          // always update the matched quantity for those which do not have updates
          // if we update the matched quantity for those which have updates no issue
          if(item.matched_quantity != newPoItem.matched_quantity) {

            item.matched_quantity = newPoItem.matched_quantity;
            item.matched_quantity_value = newPoItem.matched_quantity_value;
            item.matched_quantity_formatted_value = newPoItem.matched_quantity_formatted_value;
            
            syncPoMatchedRequired = true;
          }
        }
      }

      if(Object.keys(this.poItemsWithUpdates).length > 0) {
        this.execute_auto_export = false;
      }

      if(syncPoMatchedRequired) {
        this.record.po_items = this.po_items;
        this.syncPoMatched();
      }
    },
    getItemUniqueKey(poItem: any) {
      let itemKey = poItem.line_number;
      if(poItem.sub_line_number) {
        itemKey = itemKey + '_' + poItem.sub_line_number
      }

      if(poItem.delivery_number) {
        itemKey = itemKey + '_' + poItem.delivery_number
      }

      return itemKey as string;
    },
    updatePOData(poNumber: string, updatedItem: string) {

      this.poItemsWithUpdates[poNumber] = updatedItem;

      if(this.docAttributesModel[CONSTANTS.auto_update_po_data]) {
        this.auto_update_po_data = true;
      }

      if(!this.record.po_multi_matched || this.record.po_multi_matched == 0 || this.auto_update_po_data) {
        this.refreshAlreadyAddedItem(poNumber);
        return;
      }
    },
    onDragColumn(value: any) {
      let item = value.detail;
      
      if(item.tableColumns) {
        item = item.tableColumns;
      }

      this.updatedDragColumns(item);
    },
    async updatedDragColumns(value: any) {
      this.processing = true;
      const columnList: any = {};
      value.forEach((element: any, index: number) => {
        columnList[element.name] = this.visible_columns[element.name];
        if (columnList[element.name]) {
          columnList[element.name]['order'] = index;
        }
      });  

      try {
        let po_key = this.po_table_columns + '_' + this.record.doc_type;
        await this.updateSetting(po_key, JSON.stringify(columnList));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      } 
    },

    setDisplayDocType(doc_type: any) { 
      const type = String(doc_type);
      const label = this.displayDocType(type);
      return String(label);
    },
    splitterChanged() {
      let screenWidth = window.innerWidth;
      let dynamicWidth = (screenWidth *(100 - this.imageFieldSplitter)) / 100;
      this.dynamicWidth = dynamicWidth;
    },
    openImageInSeparateWindow() {
      let route = this.$router.resolve({ path: '/po-image' });
      window.open(
        route.href,
        '_blank',
        'toolbar=yes,scrollbars=yes,resizable=yes,left=500,width=1000,height=1000',
      );
    },
    onZoomChange(val: number) {
      this.imageZoom = val;
    },
    currentPage() {
      return this.page;
    },
    scrollToPage(pageNum: any) {
      const num = parseInt(pageNum);
      if (!num || num < 1 || !this.record.images || num > this.record.images.length) {
        return;
      }
      this.page = num;
    },
    validatePageNumber() {
      if (!this.page || this.page < 1) {
        this.page = 1;
      }
      if (this.record.images && this.page > this.record.images.length) {
        this.page = this.record.images.length;
      }
      this.scrollToPage(this.page);
    },
    prevPage() {
      if (this.page <= 1) return;
      this.page--;
    },
    nextPage() {
      if (!this.record.images || this.page >= this.record.images.length) return;
      this.page++;
    },
    toggleImageArea() {

      if(this.imageFieldSplitter >= 90) {
        this.imageFieldSplitter = 70;
      } else {
        this.imageFieldSplitter = 100;
      }

    },
    initDragableList() {
      this.dragableItems.push({title: this.$t('invoice'), componentName: 'LineItems'});

      if(this.user_settings[CONSTANTS.po_shipment_order]) {
        this.dragableItems.push({title: this.$t('po_shipment_order'), componentName: 'RceiveDeliveryLines'});
      }
    },
    async initUserSettings() {
      await this.startSettingsFetch();

      if (!this.user_settings[CONSTANTS.po_shipment_order]) {
        this.user_settings[CONSTANTS.po_shipment_order] = false;
      }

      if (this.user_settings[this.charges_table_extraction]) {
        this.isChargesModuleEnabled = true;
      }
    },
    itemSorted(e: any) {
      this.initLineItems();
    },
    async handleTolerance() {
      if (this.is_view_readonly) {
        return;
      }
      await this.getToleranceLevel();
      this.initToleranceModel();

    },
    async isDocForExtTraining() {
      if (
        !this.$route.params.ext_table_train ||
        this.$route.params.ext_table_train !== 'true'
      ) {
        return;
      }
      this.ext_table_train = true;
      this.docId = String(this.$route.query.id);
      const token = String(this.$route.query.token);
      await this.setAuthToken(token);
    },
    async getToken() {
      let token: string =
        this.token && this.token != null && this.token != ''
          ? this.token
          : await getAuthorizationToken();
      return token;
    },
    handleReadOnlyAlert() {
      if (this.record.editable == false) {
        let message = 'po_readonly_doc_warning';

        if (readOnlyDocStatus.includes(this.record.status)) {
          message = 'po_finished_doc_warning';
        }

        if (this.record.status === 'error') {
          message = 'po_error_doc_warning';
        }

        this.warning_alert = notify.warning(this.$t(message));
      }
    },

    handleReadOnly() {

      if (this.record.status != CONSTANTS.ready_for_validation) {
        this.is_view_readonly = true;
        this.allowPOTableDrag = false;
        this.trigger_document_lock = false;
        this.error_message = this.$t('READ_ONLY_MSG');
        return;
      }
      
      this.trigger_document_lock = true;

      // check for access - pass the document to check permissions based on doc_type
      if (!Acl.canUpdate(this.record)) {
        this.is_view_readonly = true;
      }

    },

    initLineItems() {
      const event = new CustomEvent('init_line_items', { detail: this.record });
      document.dispatchEvent(event);
    },
    async initPage() {
      if (!this.record || !this.record.fields) {
        return;
      }

      this.connect();
      this.table_name = this.record.tables && this.record.tables.length > 0 && this.record.tables[0].hasOwnProperty('name') ? this.record.tables[0].name : '';

      this.setViewEditable();
      this.setDataToCache();
      this.verifyIfPONumberChanged();
      this.buildPoLinesObj(this.record.po_items);
      this.initLineItems();

      await this.renderMultiplePOItems(); // First get Po items
      this.setTotallineItem();
      // this.calculateMatchedTotal();
      
      this.setActiveTab();
      this.getPoFieldValue();

      this.visible_columns = await this.getSavedColumns(this.po_table_columns + '_' + this.record.doc_type);
      this.handleTolerance();
    },

    verifyIfPONumberChanged() {
      if(this.record.hasOwnProperty('is_purchase_order_changed') && this.record.is_purchase_order_changed) {

        this.record.po_multi_matched = [];
        delete this.record.is_purchase_order_changed;
      }
    },

    setViewEditable() {
      this.record.editable = true;
      if (
        readOnlyDocStatus.includes(this.record.status) ||
        this.record.status == 'error'
      ) {
        this.record.editable = false;
      }
    },

    async saveExtAppData(show_alert = false) {
      try {
        if (show_alert) {
          this.processing = true;
        }
        const response = await this.saveExtAppDocument(this.docId);
        if (response.success === false) {
          throw response;
        }
        if (show_alert) notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    validationsForExportData() {
      if (this.record.doc_type == 'ORDER_CONFIRMATION') {
        this.record.po_multi_matched.forEach((row: any) => {
          if (row.connection_status != 'success') {
            this.confirmDecision = true;
          }
        });
      } else {
        this.saveData();
      }
    },
    setPOStatus(status: string) {
      this.record['po_status'] = status;
      this.saveData();
    },
    async saveData(show_alert = true) {
      try {
        if (this.is_view_readonly) {
          return;
        }
        if (show_alert) {
          this.processing = true;
        }
        this.isSavePending = false;
        const response = await this.saveDocument(this.docId);
        if (response.success === false) {
          throw response;
        }
        this.refreshPOinfo();
        if (show_alert) notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    refreshPOinfo () {
      let po_items = {} as dynamicObj;
      po_items = this.getPurchaseOrderData();
      for (let [key, value] of Object.entries(po_items)) {
        this.addToPoItems(key, value);
      }
    },

    goToExtractionTableView() {
      this.$router.push('/field_validation_v1/' + this.$route.params.id);
    },
    ShowStaticPO() {
      if (this.$route.fullPath.match(/PO/g)) {
        this.record.showStaticPo = '4002513646';
      }
    },

    lineItemConnected(e: any) {
      if (!this.record || this.is_view_readonly) {
        return;
      }

      if (!this.record.po_multi_matched) {
        this.record.po_multi_matched = [];
      } else if(this.record.po_multi_matched.length > 0) {
        // remove already added connection and insert new one
        this.removeOldPoConnection({detail: { data: e.detail.data }});
      }

      this.record.po_multi_matched.push(e.detail.data);

      // refresh cached list
      this.getLineItemsPoV3Ref().setConnectedLineItems();
      this.removeAccountingData();

      // update the received delivery lines status
      const po_event = new CustomEvent('po_connection_add', {detail: { data: e.detail.data }});
      document.dispatchEvent(po_event);

      // update the received delivery lines status
      const event = new CustomEvent('reload_received_delivery_lines', {});
      document.dispatchEvent(event);
      // this.debounceAutoSaveFunc();
      this.calculateMatchedTotal();
      this.isSavePending = true;
    },
    getLineItemsPoV3Ref(): any {
      let lineItemsPoV3Ref = (this.$refs.lineItemsPoV3 as any);
      if(lineItemsPoV3Ref && Array.isArray(lineItemsPoV3Ref)) {
        return lineItemsPoV3Ref[0];
      }

      return lineItemsPoV3Ref;
    },
    removeOldPoConnection(e: any) {

      if (!this.record || !this.record.po_multi_matched) {
        return;
      }

      let row = e.detail.data;
      let indexFound = null;
      let table_line_ids : string[] = this.getLineIds(row);

      mainLoop:
      for (let [index, record] of this.record.po_multi_matched.entries()) {
        let recordIds: string[] = this.getLineIds(record);

        for(let table_line_id of table_line_ids) {
          if (recordIds.includes(table_line_id)) {
            indexFound = index;
            break mainLoop;
          }
        }
      }

      if (indexFound == null) {
        return;
      }

      this.record.po_multi_matched.splice(indexFound, 1);
      this.removeAccountingData();
    },
    removeLineItemPO(e: any) {

      if (!this.record || this.is_view_readonly || !this.record.po_multi_matched) {
        return;
      }

      this.blockSaveWhileRecalculating = true;
      let isPoId = e.detail.isPoId ? true : false;
      let id = e.detail.data;
      let foundIndex = 0;

      if(isPoId) {

        foundIndex = this.removeConnectionUsingPoId(id);
        if(foundIndex != null) {
          this.reCalculateForOneLineWithMultiPos(foundIndex);
        }

      } else {
        foundIndex = this.removeConnectionUsingLineId(id);
        if(foundIndex != null) {
          this.reCalculateForOnePoWithMultiLines(foundIndex);
        }
      }

      if(foundIndex == null) {
        this.getLineItemsPoV3Ref().setConnectedLineItems();
        const event = new CustomEvent('connection_remove', { detail: {data: id, isPoId: isPoId}});
        document.dispatchEvent(event);
      }

      this.blockSaveWhileRecalculating = false;
      this.removeAccountingData();

      // update the received delivery lines status
      const event = new CustomEvent('reload_received_delivery_lines', {});
      document.dispatchEvent(event);

      // this.debounceAutoSaveFunc();
      this.calculateMatchedTotal();
      this.isSavePending = true;
    },
    removeConnectionUsingPoId(poLineId: string): any {

      let foundIndex = null;
      let subFoundIndex = null;

      mainLoop:
      for (let [index, record] of this.record.po_multi_matched.entries()) {

        if(record.hasOwnProperty('po_line_id')) {
          if(record.po_line_id == poLineId) {
            foundIndex = index;
            break mainLoop;
          }

        } else if(record.hasOwnProperty('sub_lines')) {
          for (let [sub_index, sub_line] of record.sub_lines.entries()) {
            if(sub_line.po_line_id == poLineId) {
              subFoundIndex = sub_index;
              foundIndex = index;
              break mainLoop;
            }
          }
        }
      }

      if(!foundIndex && foundIndex != 0) {
        return null;
      }

      if(!subFoundIndex && subFoundIndex != 0) {

        this.record.po_multi_matched.splice(foundIndex, 1);
        return null;
      }

      this.record.po_multi_matched[foundIndex].sub_lines.splice(subFoundIndex, 1);

      return foundIndex;

    },
    removeConnectionUsingLineId(tableLineId: string): any {

      let foundIndex = null;
      let subFoundIndex = null;
      let quantity = 0

      mainLoop:
      for (let [index, record] of this.record.po_multi_matched.entries()) {

        // check if one po is mapped against single line items
        if(record.hasOwnProperty('table_line_id')) {
          if(record.table_line_id == tableLineId) {
            foundIndex = index;
            break mainLoop;
          }
        }
        // check if one line is mapped against multiplal po items
        else if(record.hasOwnProperty('table_lines')) {

          quantity = 0;
          for (let [sub_index, table_line] of record.table_lines.entries()) {
            if(table_line.table_line_id == tableLineId) {
              subFoundIndex = sub_index;
              foundIndex = index;
            } else {
              quantity = Number(table_line.quantity) + quantity;
            }
          }
          if(subFoundIndex) {
            break mainLoop;
          }
        }
      }

      if(!foundIndex && foundIndex != 0) {
        return null;
      }

      if(!subFoundIndex && subFoundIndex != 0) {
        this.record.po_multi_matched.splice(foundIndex, 1);
        return null;
      }

      this.record.po_multi_matched[foundIndex].table_lines.splice(subFoundIndex, 1);
      this.record.po_multi_matched[foundIndex].table_line_ids.splice(subFoundIndex, 1);

      return foundIndex;

    },
    getLineIds(row: any) {

      let table_line_ids : string[] = [];

      if(row.hasOwnProperty('table_line_id')) {
        table_line_ids.push(row.table_line_id);
      } else if(row.hasOwnProperty('table_line_ids')) {
        for (let [index, table_line_id] of row.table_line_ids.entries()) {
          table_line_ids.push(table_line_id);
        }
      }
      return table_line_ids;
    },
    findPOByPoId(purchase_order_number: string, po_line_id: string): any {

      let poRow: any = null;
      const data = this.po_items[purchase_order_number];
      for(let poitem of data) {
        if(poitem.id == po_line_id) {
          poRow = poitem;
          break;
        }
      }

      return poRow;

    },
    reCalculateForOneLineWithMultiPos(foundIndex: number) {

      let matchedObj = this.record.po_multi_matched[foundIndex];
      let table_line_id = matchedObj.table_line_id;
      this.record.po_multi_matched.splice(foundIndex, 1);
      this.getLineItemsPoV3Ref().setConnectedLineItems();
      const event = new CustomEvent('connection_remove', { detail: {data: null, isPoId: true}});
      document.dispatchEvent(event);

      if(!table_line_id) {
        return;
      }

      for (let [index, po_sub_lines] of matchedObj.sub_lines.entries()) {

        let poData = this.findPOByPoId(po_sub_lines.purchase_order_number, po_sub_lines.po_line_id);

        if(poData != null) {
          this.getLineItemsPoV3Ref().makeConnectionAndsave(table_line_id, poData);
        }
      }
    },
    reCalculateForOnePoWithMultiLines(foundIndex: number) {

      let matchedObj = this.record.po_multi_matched[foundIndex];
      let po_line_id = matchedObj.po_line_id;
      let poData = this.findPOByPoId(matchedObj.purchase_order_number, po_line_id);
      this.record.po_multi_matched.splice(foundIndex, 1);
      this.getLineItemsPoV3Ref().setConnectedLineItems();
      const event = new CustomEvent('connection_remove', { detail: {data: null, isPoId: false}});
      document.dispatchEvent(event);

      if(!po_line_id || !poData) {
        return;
      }

      for (let [index, table_line] of matchedObj.table_lines.entries()) {
        this.getLineItemsPoV3Ref().makeConnectionAndsave(table_line.table_line_id, poData);
      }
    },
    getFieldValues() {
      for (let field of this.record.fields) {
        if (this.get_fields.hasOwnProperty(field.name)) {
          this.get_fields[field.name] = field.formatted_value;
        }
      }
      if (this.record.showStaticPo) {
        this.get_fields['purchase_order'] = this.record.showStaticPo;
      }
    },

    async renderMultiplePOItems() {
      try {

          const po_items = this.getPurchaseOrderData();
          if (isUndefinedOrNull(this.po_items)) {
            this.po_items = {} as dynamicObj;
          }
          // Populate all POs, then rebuild once: handlePoItemsUpdate() rescans the whole
          // record.po_items, so calling it per PO was O(N × total lines).
          let hasAny = false;
          for (const [key, value] of Object.entries(po_items)) {
            if (objLen(value) === 0) {
              continue;
            }
            this.po_items[key] = value;
            hasAny = true;
          }
          if (hasAny) {
            this.handlePoItemsUpdate();
          }
          if (this.is_view_readonly) {
            return;
          }
          await this.addPoItemsFromHeaderPO();
          await this.addPoItemsFromLineItemsPO();
          // this.cleanupPoMatched();
        } catch (e) {

        }
    },

    async fetchAddPoItems(purchase_order: string) {

      if (this.po_items[purchase_order] || this.fetched_po_items.hasOwnProperty(purchase_order)) {
        return;
      }
      let po_items = (await this.getPOitems(purchase_order)) as dynamicObj;
      this.fetched_po_items[purchase_order] = po_items;
      this.addToPoItems(purchase_order, po_items, true);
    },

     // find & add po items from header purchase order
    async addPoItemsFromHeaderPO() {

      if (!this.get_fields['purchase_order']) {
        return;
      }

      if (this.po_items[this.get_fields['purchase_order']]) {
        return;
      }

      await this.fetchAddPoItems(this.get_fields['purchase_order']);
    },

    // find & add po items from table purchase order
    async addPoItemsFromLineItemsPO () {
      if (!this.record.tables
      || this.record.tables.length == 0
      || !this.record.tables[0].hasOwnProperty('rows')
      || this.record.tables[0].rows.length == 0
      ) {
        return;
      }

      const purchase_order_columns = ['purchase_order_number', ,  'purchase_order']
      for (const [index, row] of this.record.tables[0].rows.entries()) {
          if(row.is_deleted === true) {
            continue;
          }

          for (const [index, column] of row.columns.entries()) {

            if (!purchase_order_columns.includes(column.name.toLowerCase()) || column.value === '') {
              continue;
            }

            await this.fetchAddPoItems(column.value);
          }
      }
    },

    addToPoItems(purchaseOrder: string, po_items: dynamicObj, save = false) {
      if (isUndefinedOrNull(this.po_items)) {
        this.po_items = {} as dynamicObj;
      }

      if (objLen(po_items) == 0) {
        return;
      }

      this.po_items[purchaseOrder] = po_items;

      if (save) {
        this.setPoItemsforSave();
        return;
      }
      this.handlePoItemsUpdate();
    },

    handlePoItemsUpdate() {
      this.buildPoLinesObj(this.record.po_items);
      this.setupSupplierItemNumbers(this.record.po_items);
      this.handleCharges(this.record.po_items);
    },

