    keyDownEvent(e: any) {
      if (e.key === 'Enter') {
        const el = e.target as HTMLElement;
        if (el !== null) {
          if (
            el.hasAttribute('data-id') &&
            el.getAttribute('data-id') === 'po_search'
          ) {
            this.searchPurchaseOrder();
          }
        }
      } else if (e.ctrlKey && (e.key === 'f' || e.key === 'F')) {
        e.preventDefault();
        setTimeout(() => {
          ($('#search-po') as HTMLElement).querySelector('label')!.click();
        }, 10);
      } else if (e.ctrlKey && (e.key === 'a' || e.key === 'A')) {
        e.preventDefault();
        setTimeout(() => {
          ($('#auto_po_match_btn') as HTMLElement).click();
        }, 10);
      } else if (e.ctrlKey && (e.key === 's' || e.key === 'S')) {
        e.preventDefault();
        setTimeout(() => {
          ($('#save_po_btn') as HTMLElement).click();
        }, 10);
      } else if (e.ctrlKey && (e.key === 'e' || e.key === 'E')) {
        e.preventDefault();
        const event = new CustomEvent('confirm_and_export', {});
        window.dispatchEvent(event);
      } else if (e.ctrlKey && (e.key === 'd' || e.key === 'D')) {
        e.preventDefault();
        setTimeout(() => {
          ($('#po_training_mode_btn') as HTMLElement).click();
        }, 10);
      } else if (e.ctrlKey && (e.key === 'h' || e.key === 'H')) {
        e.preventDefault();
        setTimeout(() => {
          ($('#help_po_btn') as HTMLElement).click();
        }, 10);
      } else if (e.ctrlKey && (e.key === 'k' || e.key === 'K')) {
        e.preventDefault();
        setTimeout(() => {
          ($('#keyboard_po_btn') as HTMLElement).click();
        }, 10);
      } else if (e.altKey && e.keyCode === 82) {
        e.preventDefault();
        const event = new CustomEvent('reject_document', {});
        document.dispatchEvent(event);
      } else if (e.ctrlKey && (e.key === 'm' || e.key === 'M')) {
        e.preventDefault();
        const rowElements = Array.from(this.poElements).filter(
          (el): el is HTMLTableRowElement =>
            el instanceof HTMLTableRowElement &&
            el.classList.contains('po_iterateable_item') &&
            el.classList.contains('table-row') &&
            el.classList.contains('compact-table-tr') &&
            el.classList.contains('draggable')
        );
        const poElement: HTMLElement | null = rowElements[this.currentPoElementIndex];

        if (poElement) {
          poElement.focus();
          poElement.classList.add('highlighted-row');

          poElement.addEventListener('blur', () => {
            poElement.classList.remove('highlighted-row');
          });
        }

        if (this.currentPoElementIndex < rowElements.length - 1) {
          this.currentPoElementIndex++;
        } else {
          this.currentPoElementIndex = 0;
        }
      } else if (e.ctrlKey && (e.key === 'p' || e.key === 'P')) {
        e.preventDefault();
        const rowElements = Array.from(this.poElements).filter(
          (el): el is HTMLTableRowElement =>
            el instanceof HTMLTableRowElement &&
            el.classList.contains('po_iterateable_item') &&
            el.classList.contains('table-row') &&
            el.classList.contains('compact-table-tr') &&
            el.classList.contains('draggable')
        );
        const firstPoElement: HTMLElement | null = rowElements[0];

        if (firstPoElement) {
          firstPoElement.focus();
          firstPoElement.classList.add('highlighted-row');

        }
      } 
    },
