<!--vbase-->
<template>
  <!-- Purchase Order Data -->
             <div class='q-pa-sm'>
                <ColumnFilterBadges  :name="`PurchaseOrderFilter-${po_number}`" class="q-mb-sm" @onUpdateValue="(prop: dynamicObj[]) => {filterValueByField = {...prop}}" />
                <q-table
                  class="sticky-header table_height resizable po-sub-table q-table--compact"
                  :rows="filteredTableRows"
                  :columns="tableColumns"
                  flat
                  :sort-method="customSort"
                  row-key="id"
                  :table-header-style="{ backgroundColor: '#d4d4d4' }"
                  v-model:pagination="pagination"
                  :rows-per-page-options="[0]"
                  virtual-scroll
                  :virtual-scroll-item-size="32"
                  :virtual-scroll-sticky-size-start="48"
                  :id="tableId"
                  :no-data-label="$t('no_data_found')"
                  :loading="loading_data"
                  ref="el"
                >
                <template v-slot:loading>
                  <q-inner-loading showing color="primary">
                    <q-spinner-dots size="3em" color="primary" />
                  </q-inner-loading>
                </template>
                <template v-slot:header="props">
                  <q-tr
                  :props="props"
                  :class="(allowPOTableDrag === true) ? 'draggable' : ''"
                  :draggable="allowPOTableDrag === true ? 'true' : 'false'"
                  >
                    <q-th
                      v-for="(col, index) in props.cols"
                      :id="col.name"
                      :key="col.name"
                      :props="props"
                      :draggable="allowColumSorting ?? allowedColumnSorting(col)"
                      :dropzone="allowedColumnSorting(col)"
                      :data-index="index"
                      direction="horizontal"
                      @dragstart="onDragStart($event,tableColumns,Number(index))"
                      @drop.prevent="handleDrop($event,Number(index))"
                      @dragover.prevent="onDragOverWrapper($event,index,col.name)"
                      @dragenter.prevent="onDragEnter"
                      @dragleave.prevent="onDragLeave"
                      class="po-table-header"
                      :style="{ cursor: (getIsDragging && allowedColumnSorting(col)) ? 'pointer' : 'move' }"
                      :class="(allowPOTableDrag === true) ? 'draggable' : ''"
                    >
                      <span v-if="col.label == 'position'" class="float-right">{{ col.label }}</span>
                      <span v-else
                      :class="col.is_bold || col.name === po_quantity_column ? 'text-weight-bolder font-size-14 secondary-c-text' : ''"
                    
                      >{{ col.label }}</span>
                          <ColumnFilter v-if="col.label" :persist="true"  :name="`PurchaseOrderFilter-${po_number}`" :column="col.name" @onUpdateValue="(prop: dynamicObj[]) => {filterValueByField = {...prop}}"/>
                    </q-th>
                  </q-tr>
                </template>

                <template v-slot:body="props">

                  <q-tr :props="props" :id='props.key'
                  class="po_iterateable_item table-row compact-table-tr"
                  tabindex="0"
                  :draggable="props.row['is_draggable']"
                  @click.shift="selectMultiItems(props.key, props.row, props.rowIndex)"
                  @click.ctrl="selectForMatch(props.key, props.row)"
                  @click.meta="selectForMatch(props.key, props.row)"
                  :class="((props.row['is_draggable']) ? 'draggable' : 'un-draggable') + ' '
                    + (props.rowIndex % 2 == 0 ? '' : 'alternative-row') + ' '
                    + (po_line_id_for_match.includes(props.row.id) ? 'selected_for_match' : '') + ' '
                    + getRowStyle(props.row)
                  "
                  :data-id="props.key">

                  <!-- right click menu -->
                    <q-menu @before-show="contextHandler($event, props)" context-menu v-model="props.row['show_menu']" v-if="record.editable && !is_view_readonly && !allowPOTableDrag && props.row['is_draggable']">
                      <q-list dense style="min-width: 100px">
                        <template v-if="po_line_id_for_match.includes(props.key)">
                            <q-item clickable  v-close-popup
                          @click="removeMatch(props.key, props.row)">
                            <q-item-section>{{$t('unselect')}}</q-item-section>
                          </q-item>
                          <q-item clickable  v-close-popup
                          @click="clearMatch()">
                            <q-item-section>{{$t('clear')}}</q-item-section>
                          </q-item>
                        </template>
                        <q-item v-else clickable  v-close-popup
                        @click="selectForMatch(props.key, props.row)">
                          <q-item-section>{{$t('select_for_match')}}</q-item-section>
                        </q-item>
                      </q-list>

                    </q-menu>

                    <template v-for="(col) in props.cols" :key="col.name" :props="props">

                      <q-td v-if="col.name === 'connection_status'" :data-id="props.key" class="actions" :class="(props.row['is_draggable']) ? 'draggable' : 'un-draggable'">
                        <q-img v-if="isChargesModuleEnabled" @click="toggleExpand(props.row)" :class="!getPoLineCharges(props.row.line_number) ? 'item-disabled' : 'cursor-pointer'"
                            src="/images/charges/charges.svg" height="21px" width="19px" class="icon-grey-svg" id="icon_charge">

                          <q-tooltip>
                            {{$t('charges')}}
                          </q-tooltip>
                      </q-img>
                        <f-btn appearance="tertiary" @click="props.expand = !props.expand" :icon="props.expand ? 'remove' : 'add'"  class="q-mr-sm"/>
                        <template v-if="props.row.connected">
                          <template v-if="props.row.connection_data.connection_status == 'success'">
                            <q-icon size="sm" name='done' class='success'>
                              <q-tooltip>
                                {{ $t('po_connected_match') }}
                              </q-tooltip>
                            </q-icon>
                          </template>
                          <template v-else>
                            <q-icon size="sm" name='done' class='mismatched'>
                              <q-tooltip>
                                {{ $t('po_connected_mismatch') }}
                              </q-tooltip>
                            </q-icon>
                          </template>
                        </template>
                      </q-td>

                      <q-td v-else-if="col.name === 'status'" :data-id="props.key" :class="(props.row['is_draggable']) ? 'draggable' : 'un-draggable'">
                          <q-badge transparent align="middle" :color="statusColor(props.row[col.name])" v-if="props.row[col.name]">
                            {{ props.row[col.name] }}
                          </q-badge>
                      </q-td>

                      <q-td v-else :data-id="props.key" :class="(props.row['is_draggable']) ? 'draggable' : 'un-draggable'">
                          <span :class="col.is_amount ? 'float-right' : ''">
                            {{ props.row[col.name] }}
                          </span>
                      </q-td>

                    </template>

                  </q-tr>

                  <q-tr v-if="props.expand && (!po_connected_line_items[props.key] || po_connected_line_items[props.key].hasOwnProperty('table_line_id'))" :props="props" class="charges-row compact-table-tr">
                    <q-td></q-td>
                    <template v-for="(col, colIndex) in props.cols.slice(1)" :key="'no-match-' + col.name">
                      <q-td v-if="colIndex === 0">No multi-match Information</q-td>
                      <q-td v-else></q-td>
                    </template>
                  </q-tr>
                  <q-tr v-if="props.expand && po_connected_line_items[props.key] && !po_connected_line_items[props.key].hasOwnProperty('table_line_id')" :props="props" class="charges-row compact-table-tr">
                    <q-td></q-td>
                    <template v-for="(col, colIndex) in props.cols.slice(1)" :key="'multi-header-' + col.name">
                      <q-td v-if="colIndex === 0" class="charges-header-cell">{{ $t('position') }}</q-td>
                      <q-td v-else-if="colIndex === 1" class="charges-header-cell text-right">{{ $t('quantity') }}</q-td>
                      <q-td v-else-if="colIndex === 2" class="charges-header-cell text-right">{{ $t('unit_price') }}</q-td>
                      <q-td v-else></q-td>
                    </template>
                  </q-tr>
                  <template v-for="(table_line, index) in po_connected_line_items[props.key]?.table_lines" :key="'multi-' + table_line.table_line_id">
                    <q-tr v-if="props.expand && po_connected_line_items[props.key] && !po_connected_line_items[props.key].hasOwnProperty('table_line_id')" :props="props" class="charges-row compact-table-tr">
                      <q-td></q-td>
                      <template v-for="(col, colIndex) in props.cols.slice(1)" :key="'multi-data-' + col.name + '-' + index">
                        <q-td v-if="colIndex === 0" :class="{ 'charges-data-cell': true, 'charges-alt-cell': +index % 2 !== 0 }">{{ lineDataObj[table_line.table_line_id]?.columns?.POSITION?.formatted_value }}</q-td>
                        <q-td v-else-if="colIndex === 1" :class="{ 'charges-data-cell': true, 'charges-alt-cell': +index % 2 !== 0, 'text-right': true }">{{ lineDataObj[table_line.table_line_id]?.columns?.QUANTITY?.formatted_value }}</q-td>
                        <q-td v-else-if="colIndex === 2" :class="{ 'charges-data-cell': true, 'charges-alt-cell': +index % 2 !== 0, 'text-right': true }">{{ lineDataObj[table_line.table_line_id]?.columns?.UNIT_PRICE?.formatted_value }}</q-td>
                        <q-td v-else></q-td>
                      </template>
                    </q-tr>
                  </template>

                  <!-- Spacer row between multi-match and charges -->
                  <q-tr v-if="props.expand && props.row.expand" :props="props" class="compact-table-tr">
                    <q-td :colspan="props.cols.length"></q-td>
                  </q-tr>

                  <q-tr v-if="props.row.expand" :props="props" class="charges-row compact-table-tr">
                    <q-td></q-td>
                    <template v-for="(col, colIndex) in props.cols.slice(1)" :key="'header-' + col.name">
                      <q-td v-if="colIndex === 0" class="charges-header-cell">{{ $t('charge_id') }}</q-td>
                      <q-td v-else-if="colIndex === 1" class="charges-header-cell text-right">{{ $t('amount') }}</q-td>
                      <q-td v-else-if="colIndex === 2" class="charges-header-cell">{{ $t('charge_type') }}</q-td>
                      <q-td v-else-if="colIndex === 3" class="charges-header-cell">{{ $t('purchase_order_number') }}</q-td>
                      <q-td v-else></q-td>
                    </template>
                  </q-tr>
                  <template v-for="(table_line, chargeIndex) in props.row.po_charge_item" :key="'charge-' + table_line.line_number">
                    <q-tr v-if="props.row.expand && table_line.charge_id" :props="props" class="charges-row compact-table-tr">
                      <q-td></q-td>
                      <template v-for="(col, colIndex) in props.cols.slice(1)" :key="'data-' + col.name + '-' + chargeIndex">
                        <q-td v-if="colIndex === 0" :class="{ 'charges-data-cell': true, 'charges-alt-cell': +chargeIndex % 2 !== 0 }">
                          <q-icon v-if="costingElementDictionary && costingElementDictionary[table_line.charge_id]" :name="'img:images/charges/' + costingElementDictionary[table_line.charge_id].icon" size="xs" class="icon-grey-svg q-mr-sm"/>
                          <span>{{ table_line.charge_id }}</span>
                        </q-td>
                        <q-td v-else-if="colIndex === 1" :class="{ 'charges-data-cell': true, 'charges-alt-cell': +chargeIndex % 2 !== 0, 'text-right': true }">{{ table_line.formattedAmount }}</q-td>
                        <q-td v-else-if="colIndex === 2" :class="{ 'charges-data-cell': true, 'charges-alt-cell': +chargeIndex % 2 !== 0 }">{{ table_line.charge_type }}</q-td>
                        <q-td v-else-if="colIndex === 3" :class="{ 'charges-data-cell': true, 'charges-alt-cell': +chargeIndex % 2 !== 0 }">{{ table_line.purchase_order_number }}</q-td>
                        <q-td v-else></q-td>
                      </template>
                    </q-tr>
                  </template>
                </template>
                

                </q-table>
            </div>

            <!-- END Purchase Order Data -->
</template>

<script lang='ts'>

import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { SessionStorage } from 'quasar';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import docTablesUtil from 'src/utils/docTablesUtil';
import { ApiExceptions } from 'src/exceptions/index';
import { type dynamicObj, $ } from 'src/pages/assets';
import dragDropColumn from 'src/mixins/dragDropColumn';
import ColumnFilter from '../Dashboard/ColumnFilter.vue';
import resizableGridUtil from 'src/utils/resizableGridUtil';
import { notify } from 'src/components/notifications/notify';
import lineItemsBaseMixin from 'src/mixins/lineItemsBaseMixin';
import { isUndefinedOrNull, objLen } from 'src/utils/general';
import { charges_table_extraction, CONSTANTS } from 'src/constants';
import ColumnFilterBadges from '../Dashboard/ColumnFilterBadges.vue';
import { useTableHeightResize } from 'src/utils/tableHeightResizeUtil';
import { AMOUNT_COLUMNS } from 'src/pages/PurchaseOrders/constants.js';
import {
  colValue as colValueUtil,
  allowedColumnSorting as allowedColumnSortingUtil,
  statusColor as statusColorUtil,
  formatPoDateFields,
} from 'src/pages/PurchaseOrders/purchaseOrderTableUtils';
import {
  usePoMatchStore,
  useSettingStore,
  useDocumentStore,
  useAmountFormatStore,
  useDocAttributesStore,
  useMasterDataLookupStore,
} from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [dateUtils, docTablesUtil, helperUtil, dragDropColumn, resizableGridUtil, lineItemsBaseMixin],
  props: {
    visible_columns: {
      type: Object,
      default: ()=>({})
    },
    po_lines: {
      type: Array,
      default: ()=>[],
    },
    po_number: {
      type: String,
      default: ''
    },
    allowPOTableDrag: {
      type: Boolean,
      default: false
    },
  },
  components: {ColumnFilter, ColumnFilterBadges},
  data() {
    return {
      AMOUNT_COLUMNS,
      loading_data: true,
      is_preparing: false,
      deferInitRaf: 0,
      deferInitTimer: null as ReturnType<typeof setTimeout> | null,
      // Virtualized: a PO can have 8k+ lines, so keep only the visible rows in the DOM.
      pagination: { rowsPerPage: 0 } as dynamicObj,
      po_connected_line_items: {} as {[k: string]: any},
      additional_columns: [ 'delivery_number', 'delivery_line_number', ] as string[],
      po_charge_item: {} as dynamicObj,
      formattedAmount: ref(''),
      scrollItemIndex: 0,
      lastScrollPoLineId: '',
      selectedRow: [] as string[],
      filterValueByField: ref({}) as dynamicObj,
      draggingColumnIndex: -1 as number,
      isDragging: ref(false),
      scrollInterval: null as unknown as number,
      tableColumnsOriganl: ref([] as any),
      indexToMove: ref(),
      oldIndex: ref(),
      tableId: 'po-table',
    };
  },
  mounted: async function() {
    document.addEventListener('init_po_lines', this.loadPurchaseOrderData);
    document.addEventListener('removed_highlight', this.removeHighlights);
    document.addEventListener('po_connection_add', this.lineItemConnected);
    document.addEventListener('connection_remove', this.connectionRemoved);
    document.addEventListener('show_line_highlighted', this.showLineHighlighted);
    document.addEventListener('scroll_to_highlighted_line', this.scrollToHighlightedLine);
    this.initailizeDragColumnsById(this.tableId);
    if(this.user_settings[charges_table_extraction]) {
      await this.prepareCostingElementDictionary();
    }
    // Defer the heavy row build past the next paint so the tab switches instantly.
    this.deferInitRaf = requestAnimationFrame(() => {
      this.deferInitTimer = setTimeout(() => {
        this.loadPurchaseOrderData();
      }, 120);
    });

    document.addEventListener('dragend', this.dragend);
    document.addEventListener('dragstart', this.dragstart);
    document.addEventListener('keydown',  this.keyDownEvent);

    await this.$nextTick();
    this.initTableColumnResize(this.tableId);

  },
  unmounted: function() {
    // Don't let a deferred build run on a dead instance (fast tab switch).
    cancelAnimationFrame(this.deferInitRaf);
    if (this.deferInitTimer) {
      clearTimeout(this.deferInitTimer);
    }
    document.removeEventListener('dragend', this.dragend);
    document.removeEventListener('dragstart', this.dragstart);
    document.removeEventListener('keydown', this.keyDownEvent);
    document.removeEventListener('removed_highlight', this.removeHighlights);
    document.removeEventListener('po_connection_add', this.lineItemConnected);
    document.removeEventListener('connection_remove', this.connectionRemoved);
    document.removeEventListener('init_po_lines', this.loadPurchaseOrderData);
    document.removeEventListener('show_line_highlighted', this.showLineHighlighted);
    document.removeEventListener('scroll_to_highlighted_line', this.scrollToHighlightedLine);

    this.destoryAndRest(this.tableId);
    this.clearDraggingData();
  },
  watch: {
    // Shallow — po_items[po] is replaced wholesale, so the prop ref changes. A deep watch
    // tracked every property of 2k+ row objects on every change: pure overhead.
    po_lines: function () {
      this.loadPurchaseOrderData();
    },
    charges: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.prepareChargesForLines(newVal);
      },
    },
  },
  computed: {
    filteredTableRows() {
        return this.filterByObject(this.tableRows,this.filterValueByField)
      }
  },
  methods: {
    colValue(row: any, col_name: any) {
      return colValueUtil(row, col_name);
    },

    onDragOverWrapper(event: any,index: any,name: string) {
      if(name == 'connection_status') return;
      this.onDragOver(event,index);
    },
    allowedColumnSorting(column: any) {
      return allowedColumnSortingUtil(column);
    },
    isNotEditable() {
      return !this.record.editable || this.is_view_readonly;
    },
    contextHandler(event: any, props: any) {
      //control + left click event for purchase order row for MACOS
      if(event.ctrlKey && event.buttons == 1){
        this.selectForMatch(props.key, props.row);
        props.row['show_menu'] = false;
      }
      else if(event.buttons == 2){
        props.row['show_menu'] = true;
      }
    },
    clearMatch(){
      if (this.isNotEditable()) {
        return;
      }
      this.po_line_id_for_match = [];
      this.po_line_for_match = [];
      for (let [index, row] of this.tableRows.entries()) {
        row['show_menu'] = false;
      }
    },
    removeMatch (row_key: string,row: dynamicObj) {
      try {
        if (this.isNotEditable()) {
          return;
        }
        const index = this.po_line_id_for_match.indexOf(row_key);
        this.po_line_id_for_match.splice(index,1)
        this.po_line_for_match.splice(index,1)
        row['show_menu'] = false;
      } catch (err) {
        logError(err);
      }

    },

    selectMultiItems (po_line_id: string, row: dynamicObj, currentIndex: number) {

      if(this.po_line_id_for_match.length == 0) {
        this.selectForMatch (po_line_id, row);
        return;
      }

      if (this.isNotEditable() || row.is_draggable === false) {
        return;
      }

      // if item exists then remove it
      if (this.removeSelectedItemIfExists(po_line_id)) {
        return;
      }

      const lastItemId = this.po_line_id_for_match.at(-1);

      // get all Rows of table
      const rowItems = this.filterByObject(this.tableRows, this.filterValueByField);

      const lastItemIndex = rowItems.findIndex(item => item.id === lastItemId);

      let startingIndex = currentIndex;
      let endingIndex = lastItemIndex;

      if(startingIndex > endingIndex) {
        startingIndex = lastItemIndex;
        endingIndex = currentIndex;
      }

      for(let i = startingIndex; i <= endingIndex; i++) {
        this.removeSelectedItemIfExists(rowItems[i].id);
        this.po_line_id_for_match.push(rowItems[i].id);
        this.po_line_for_match.push(rowItems[i]);
      }

    },
    selectForMatch (po_line_id: string, row: dynamicObj) {
      try {
        if (this.isNotEditable() || row.is_draggable === false) {
          return;
        }

        // if item exists then remove it
        if (this.removeSelectedItemIfExists(po_line_id)) {
          return;
        }
       
        this.po_line_id_for_match.push(po_line_id);
        this.po_line_for_match.push(this.getTargetRow(po_line_id));
        // if (!this.po_line_for_match) {
        //   this.po_line_id_for_match = '';
        //   this.po_line_for_match = {} as dynamicObj;
        // }
        row['show_menu'] = false;
      } catch (err) {
        logError(err);
      }

    },
    removeSelectedItemIfExists(po_line_id: string) {
      const existedIndex = this.po_line_id_for_match.indexOf(po_line_id)
      if(existedIndex > -1){
        this.po_line_id_for_match.splice(existedIndex,1)
        this.po_line_for_match.splice(existedIndex,1)
        return true;
      }

      return false;
    },
    dragend(event: any){
      // document.removeChild(document.getElementById('ghost') as HTMLElement)
    },
    dragstart(event: any) {
        let id = event.target.dataset.id;
        //if target doesn't have id then return (only draggable purchase order row have dataset id)
        if(!id) return;
        //clear the selected rows if they dragging the non selected one
        if(!this.po_line_id_for_match.includes(id)){
          this.po_line_id_for_match = [];
        }
        //push the dragging id to selected rows array
        if(this.po_line_id_for_match.length == 0) {
          this.po_line_id_for_match.push(id);
        }

        //create ghost element when dragging for visualisation
        if(this.po_line_id_for_match.includes(id)){
          const ghostEl = document.createElement('tbody');
          this.po_line_id_for_match.forEach((po_line_id: string) => {
              const targetElement = document.querySelector(`[data-id="${po_line_id}"]`);
              if(targetElement){
                const row = targetElement.cloneNode(true) as any;
                
                // Remove class float-right from all children and keep only the first 
                // 10 children to prevent ghost element from being too wide
                Array.from(row.children).forEach((child, index) => {
                    (child as HTMLElement).classList.remove('float-right');
                    (child as HTMLElement).style.backgroundColor = '#2388AE42';
                    if (index >= 10) {
                        row.removeChild(child);
                    }
                });

                ghostEl.appendChild(row);
              }
          });
          ghostEl.id = 'ghost';
          ghostEl.style.position = 'absolute'; 
          ghostEl.style.top = '-1000px'; 
          ghostEl.style.left = '-1000px';
          document.body.appendChild(ghostEl);
          event.dataTransfer.setDragImage(ghostEl, 0, 0);
          setTimeout(() => {
            //remove old element so the dragImage won't duplicate when dragging
            document.getElementById('ghost')?.remove()
          })
        }
        
        
        if (!event.target || this.isNotEditable()) {
          return;
        }

        if(this.allowPOTableDrag === true) {
          SessionStorage.set('DRAG_PO_NUMBER', String(this.po_number));
        }
        // else {

        //   const targetRow = this.getTargetRow(id);
        //   if (targetRow) {
        //     SessionStorage.set('Text', JSON.stringify(targetRow));
        //   }
        // }
    },

    getTargetRow (po_line_id: string) {
      try {
        const targetPoLine = this.PODataObj[po_line_id];
        let targetRow = {} as dynamicObj;
        for (let [index, row] of this.tableRows.entries()) {
          if(row.id == po_line_id) {
            targetRow = row;
            break;
          }
        }
        targetRow = Object.assign(targetRow, targetPoLine);
        return targetRow;
      } catch (err) {
        logError(err);
        return {} as dynamicObj;
      }
    },

    loadPurchaseOrderData() {
      // The po_lines watcher and the init_po_lines event can both fire this; is_preparing
      // guards overlapping runs. loading_data only drives the overlay.
      if (this.is_preparing) {
        return;
      }
      this.is_preparing = true;
      this.loading_data = true;
      try {
        this.setConnectedPoRecords();
        this.checkForAdditionalColumns();
        this.prepareTableColumn();
        this.prepareTableRows();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading_data = false;
        this.is_preparing = false;
        // Replaces the updated() hook that re-applied this on every re-render.
        this.$nextTick(() => {
          this.applyStoredHeight(this.tableId);
          this.resetAndReInitColumnResize(this.tableId);
        });
      }
    },
    prepareTableColumn() {
      this.tableColumns = [];

      // empty Column for buttons
      let columnItem = { name: 'connection_status', field: 'connection_status', align: 'left', label: '', order: 0}
      this.tableColumns.push(columnItem);
      Array.from(Object.keys(this.visible_columns)).forEach((columnKey: string) => {
        let column = this.visible_columns[columnKey];
          let item = {
            name: column.name,
            field: column.name,
            align: 'left',
            label: this.$t(column.translation_key),
            sortable: true,
            is_bold: this.isColumnBold(column.name),
            is_amount: this.checkIfColumnIsAmount(column.name, this.AMOUNT_COLUMNS),
            order: column.order
          }

          this.tableColumns.push(Object.assign({}, item));
         
      });
      // sort
      this.tableColumns.sort((a: any, b: any) => {
        return a.order - b.order;
      });

      this.tableColumnsOriganl = JSON.parse(JSON.stringify(this.tableColumns));

    },

    // addAdditionalColumns () {
    //   let order = 25;
    //   console.log(this.tableColumns,'additional column herer')
    //   for (let [col_index, name] of Object.entries(this.additional_columns)) {
    //       //if we have already added the column then skip
    //       console.log(this.tableColumns.find((col: any) => col.name == name) ,'additional column herer',name)
    //       if(this.tableColumns.find((col: any) => col.name == name)) {
    //         continue;
    //       }
    //       let item = {
    //         name: name,
    //         field: name,
    //         align: 'left',
    //         label: this.$t(name),
    //         sortable: true,
    //         is_bold: this.isColumnBold(name),
    //         order: order++,
    //       }
    //       this.tableColumns.push(Object.assign({}, item));
    //     }
    // },
    isColumnBold(columnName: string) {
      return false;
    },

    prepareTableRows() {
      if (!this.po_lines || this.po_lines.length == 0) {
        this.tableRows = [];
        return;
      }

      // Hoist loop invariants and assign tableRows once — one reactive write, not one per row.
      const columns = this.tableColumns as dynamicObj[];
      const connectedItems = this.po_connected_line_items;
      const disabledStatuses = this.doc_attributes['PO_DISABLED_STATUSES'];
      const chargesForPo = this.charges[this.po_number];
      const rows = this.po_lines as any[];
      const newRows: dynamicObj[] = new Array(rows.length);

      for (let i = 0; i < rows.length; i++) {
        const row = rows[i];
        const newRow: dynamicObj = {
          connection_data: {},
          connected: false,
          id: row.id,
          show_menu: false,
          line_number: row.line_number,
        };

        if (isUndefinedOrNull(row.status)) {
          row.status = '';
        }
        newRow['is_draggable'] = !(
          disabledStatuses && disabledStatuses.includes(row.status.toLowerCase())
        );

        const connection = connectedItems[row.id];
        if (connection !== undefined) {
          newRow['connected'] = true;
          newRow['connection_data'] = connection;
        }

        for (let c = 0; c < columns.length; c++) {
          const name = columns[c].name;
          // Baked in so the template reads props.row[name] instead of calling colValue() per cell.
          newRow[name] = this.colValue(row, name);

          // Also store unformatted value
          const columnValueKey = name + '_value';
          if (row[columnValueKey] !== undefined) {
            newRow[columnValueKey] = row[columnValueKey];
          }
        }

        if (chargesForPo) {
          newRow['charges'] = this.charges[row.line_number];
        }

        this.formateDateFields(newRow);
        newRows[i] = newRow;
      }

      this.tableRows = newRows;
    },
    formateDateFields(newRow: any) {
      formatPoDateFields(newRow, this.formatDateAccordingToPreference.bind(this));
    },

    checkForAdditionalColumns () {
      if (this.po_lines.length == 0) {
        return;
      }
      // if any of the columns has value then add all of them in the columns list
      this.po_lines.forEach((row: any, index: any) => {
        for (let [col_index, name] of Object.entries(this.additional_columns)) {
          const columnName = name as string;
          if (row.hasOwnProperty(columnName) && row[columnName] != null && row[columnName] != '') {
            this.add_additional_columns = true;
            break;
          }
        }
      });
    },

    lineItemConnected (e: any) {

      let data = e.detail.data;

      let ids: string[] = [];
      if(data.hasOwnProperty('po_line_id')) {
        ids.push(data.po_line_id);
      } else if(data.hasOwnProperty('sub_lines')) {
        for (let [index, po_sub_lines] of data.sub_lines.entries()) {
          ids.push(po_sub_lines.po_line_id);
        }
      }

      // let connected = false;
      for (let [index, row] of this.tableRows.entries()) {

        for(let id of ids) {
          if(row.id == id) {
            row.connected = true;
            row.connection_data = data;

            this.po_connected_line_items[id] = data;
            // connected = true;
          }
        }

      }

      // if (connected) {
      //   const event = new CustomEvent('po_connection_success', { detail: e.detail});
      //   document.dispatchEvent(event);
      // }
    },
    connectionRemoved (e: any) {

      this.setConnectedPoRecords();
      this.prepareTableRows();

      // this.removeConnectionEntryFromPoLine(id);
    },
    removeConnectionEntryFromPoLine (id: string) {
      for (let [index, row] of this.tableRows.entries()) {
        if(row.id == id) {
          row.connected = false;
          row.connection_data = null;
          break;
        }
      }
    },
    setConnectedPoRecords () {
      this.po_connected_line_items = {} as dynamicObj;
      let po_matching = this.getConnectedLineItems();

      if (po_matching.length == 0) {
        return;
      }
      for (let [index, record] of po_matching.entries()) {
        if(record.hasOwnProperty('po_line_id')) {
          this.po_connected_line_items[record.po_line_id] = record;
        } else if(record.hasOwnProperty('sub_lines')) {
          for (let [index, po_sub_lines] of record.sub_lines.entries()) {
            this.po_connected_line_items[po_sub_lines.po_line_id] = record;
          }
        }

      }
    },
    clearDraggingData() {
      SessionStorage.remove('Text');
    },
    showConnectedLines (e: any) {
      for (let [index, row] of this.tableRows.entries()) {
        if (row.show == false) {
          row.show = true;
        }
      }
    },
    showLineHighlighted (e: any) {
      // TODO

      if (!e.detail
      || (
        !e.detail.hasOwnProperty('sub_lines') && !e.detail.hasOwnProperty('po_line_id')
        )
      ) {
        return;
      }

      const po_line_ids = this.getPoLineIds(e.detail);
      if (po_line_ids.length == 0) {
        return;
      }

      this.removeHighlights();

      let connection_info = e.detail;
      for (let [index, po_line_id] of po_line_ids.entries()) {
        this.highlightRow(po_line_id, connection_info);
      }
    },
    scrollToHighlightedLine(e: any){
      let po_line_id = e.detail.po_line_id;
      
      if(!po_line_id){
        if(this.lastScrollPoLineId !== e.detail.table_line_id ){
          this.scrollItemIndex = e.detail.sub_lines.length - 1
          this.lastScrollPoLineId = e.detail.table_line_id
        }else{
          if(this.scrollItemIndex == 0){
            this.scrollItemIndex = e.detail.sub_lines.length - 1
          }else{
            this.scrollItemIndex = this.scrollItemIndex - 1;
          }
        }
        po_line_id = e.detail.sub_lines[this.scrollItemIndex].po_line_id;
    
      }
      let tr = document.querySelector('[data-id="' + po_line_id+'"]') as HTMLElement;
      if (!tr) {
        notify.error(this.$t('PO_LINES_ARE_HIDDEN'));
        return;
      }
      tr.scrollIntoView({behavior: 'smooth', block: 'center', inline: 'nearest'});
    },
    highlightRow (po_line_id: string, connection_info: any) {
      let tr = document.querySelector('[data-id="' + po_line_id+'"]') as HTMLElement;
      if (!tr) {
        notify.error(this.$t('PO_LINES_ARE_HIDDEN'));
        return;
      }

      if (connection_info['connection_status'] == 'success') {
        tr.classList.add('highlighted','line-success');
      }

      if (connection_info['connection_status'] == 'mismatch') {
        tr.classList.add('highlighted','line-mismatched');
      }
    },

    getPoLineIds (connection: any) {

      try {
        const po_line_ids = [] as string[];
        if (connection.hasOwnProperty('sub_lines')) {
          for (let [index, po_sub_lines] of connection.sub_lines.entries()) {

            if (this.po_number !== this.PODataObj[po_sub_lines.po_line_id].purchase_order_number) {
              continue;
            }
            po_line_ids.push(po_sub_lines.po_line_id);
          }
        } else if (this.po_number == this.PODataObj[connection.po_line_id].purchase_order_number) {
          po_line_ids.push(connection.po_line_id);
        }

        return po_line_ids;
      } catch (err) {
        logError(err);
        return [];
      }

    },

    removeHighlights(e?: any) {
      if (e && e.detail && e.detail.purchase_order_number && this.po_number !== e.detail.purchase_order_number) {
        return;
      }

      let trs = document.querySelectorAll<HTMLElement>('.highlighted');
      for (var i = 0; i < trs.length; i++) {
        trs[i].classList.remove('highlighted','line-mismatched','line-success');
      }
    },
    keyDownEvent(e : any) {
        if (this.is_view_readonly) {
          return;
        }
        if ((e.ctrlKey || e.altKey) && e.keyCode === 67) {
          e.preventDefault();

          let selectedElement : Element | null = document.activeElement;
          if(!selectedElement || !selectedElement.classList.contains('draggable')) {
            return;
          }
          this.dragstart(e);
        }
    },

    statusColor (status: string) {
      return statusColorUtil(status);
    },
    startResize(e:any) {
      this.startY = e.clientY;
      this.isResizing = true;
      document.addEventListener('mousemove', this.resize);
      document.addEventListener('mouseup', this.stopResize);
    },
    resize(e:any) {
      if (this.isResizing) {
        const dy = e.clientY - this.startY;
        this.tableHeight += dy;
      }
    },
    stopResize() {
      this.isResizing = false;
      document.removeEventListener('mousemove', this.resize);
      document.removeEventListener('mouseup', this.stopResize);
    },
    searchValueByKey(key: string, values: dynamicObj[]) {
      return useAmountFormatStore().searchValueByKey(key, values)
    },
    async formatAmount(amount: string) {            
      const values = [];
      if (amount) {
        values.push({
            key: amount,
            value: amount
        })
      } else {
        values.push({
            key: 0,
            value: 0
        })
      }
      const { user_settings } = useSettingStore();
      const result = await useAmountFormatStore().formatMultiValues(values, 'en_US', user_settings.AMOUNTS_LOCALE);
      
      if (result) {
        const re = this.searchValueByKey(amount, result);
        return this.formattedAmount = re;
      }
    },
    async toggleExpand(row: any) {
      const charges = this.getPoLineCharges(row.line_number);
      if (charges) {
        row.po_charge_item = charges;

        if (row.po_charge_item) {
          for (const charge of row.po_charge_item) {
            charge.formattedAmount = await this.formatAmount(charge.amount);
          }
        }
      }
      row.expand = !row.expand;
    },
    getPoLineCharges(po_line_number: string) {
      const charge = this.charges[this.po_number] as dynamicObj;
      if (charge && charge[po_line_number]) {
        return charge[po_line_number] as dynamicObj;
      }
      return false;
    },

    prepareChargesForLines (charges: dynamicObj) {
      if (objLen(charges) == 0) {
        return;
      }
    },
    getRowStyle(row: any) {

      if(!this.doc_attributes || !this.doc_attributes[CONSTANTS.CONSUMED_PO_LINE_STATUS]) {
        return '';
      }
      if(!row.matched_quantity || row.matched_quantity == 0) {
        return '';
      }

      if(row[this.po_quantity_column] > row.matched_quantity) {
        return 'bg-status-orrange'
      }

      if(row[this.po_quantity_column] <= row.matched_quantity) {
        return 'bg-status-blue'
      }
      
    },
  },
  setup() {
    let data : any = [];
    const el = ref() as any;
    const doc_attribute_store = useDocAttributesStore();
    const {  model:doc_attributes  } = storeToRefs(doc_attribute_store);

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    // Table height resize functionality using the utility
    const { applyStoredHeight, initResizeObserver } = useTableHeightResize(el, {
      settingKey: 'PO_TABLE_SETTING',
      minHeight: 200
    });

    // Initialize the resize observer
    initResizeObserver();

    const po_match_store = usePoMatchStore();
    const {
      lineDataObj,
      is_view_readonly,
      PODataObj,
      po_line_id_for_match,
      po_line_for_match,
      line_connected_items,
      po_quantity_column,
      isChargesModuleEnabled,
      charges,
      add_additional_columns
    } = storeToRefs(po_match_store);
    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    const master_data_lookup = useMasterDataLookupStore();
      const { prepareCostingElementDictionary } = master_data_lookup;
      const { costingElementDictionary } = storeToRefs(master_data_lookup);

    return {
      el,
      prepareCostingElementDictionary,
      costingElementDictionary,
      isChargesModuleEnabled,
      charges,
      user_settings,
      po_quantity_column,
      line_connected_items,
      po_line_id_for_match,
      po_line_for_match,
      PODataObj,
      record,
      is_view_readonly,
      lineDataObj,
      doc_attributes,
      tableRows: ref(data),
      tableColumns:ref(data),
      add_additional_columns,
      tableHeight: ref(300), // Initial height
      startY: 0,
      isResizing: false,
      applyStoredHeight
    };
  }
});
</script>

